import type { BiomarkerInput, EntityInput, PaperInput, TargetInput, TermInput } from "@/lib/schema";
import type { Spike, SpikeSupplement } from "./index";

/**
 * PROSTATE CANCER, MOLECULAR LAYER. Facts checked 25 September 2026.
 *
 * Prostate cancer is the one common solid tumour whose driver was named before its genes were: the androgen receptor
 * is the spine of the disease from diagnosis to death, and almost every molecular story here is a story about what
 * happens to that receptor or about what a tumour does when it can no longer use it. So this file starts with the
 * receptor (`prostateArAxis`: amplification, the enhancer, ligand-binding-domain mutations, AR-V7, and why castration
 * resistance is still AR-driven), then the genomic landscape with every frequency carrying its cohort
 * (`prostateMolecularLandscape`), then DNA repair as the one axis that changes treatment and changes a family's
 * future (`prostateDnaRepair`, `prostateParpEligibility`), the primary-tumour taxonomy that fusions and SPOP define
 * (`prostateSubtypes`), PSMA as an imaging and therapeutic target (`prostatePsma`), the lineage change that ends
 * many of these illnesses (`prostateNepc`), resistance mechanism by mechanism with what follows from each
 * (`prostateResistance`), and liquid biopsy with what it can and cannot answer here (`prostateLiquidBiopsy`).
 *
 * Sources and rules. Every frequency names its cohort, its size and the paper it was read from. Figures marked
 * "cBioPortal" were computed on 25 September 2026 from the public cBioPortal API (read-only) on the named study id:
 * the count of samples carrying a non-synonymous mutation (or a high-level amplification or deep deletion in the
 * discrete copy-number profile, or a structural variant) over that study's sequenced, copy-number or structural-
 * variant sample list. They are sample-level frequencies for the study as deposited, not the papers' own
 * percentages, which are quoted alongside where the abstract gives them. Three cautions apply to this disease in
 * particular and are repeated on the rows they affect. First, stage dominates everything: a figure from a resected
 * primary tumour and a figure from a bone metastasis taken at castration resistance are measurements of different
 * diseases, so the cohorts are grouped by stage rather than averaged. Second, the metastatic whole-exome deposits
 * (prad_su2c_2019, prad_su2c_2015, prad_fhcrc) call high-level amplification on chromosome arms that are gained as a
 * block, so passenger genes sitting near a real amplicon (NBN, BRIP1, ATR, RAD51C, PMS2) read high there; only AR,
 * MYC and the ETS loci are quoted as focal events from those deposits. Third, fusion counts come from the
 * structural-variant profile, so a cohort with no SV profile reads zero for TMPRSS2-ERG rather than negative.
 *
 * Taxonomy. Nothing here is a cancer record. BRCA-altered, PTEN-null, AR-V7-positive and treatment-emergent
 * neuroendocrine disease are biomarker states, and they are written as biomarker readouts and landscape rows
 * (docs/CANCER-PAGES.md). The four existing prostate state records (prostate-mcrpc, prostate-mhspc, prostate-nmcrpc,
 * prostate-nepc) are used for their URLs and are not added to.
 *
 * Ownership. This layer owns the molecular records: the landscape, the biomarker readouts and their thresholds, the
 * target prevalence rows and the landscape papers. The trials of PARP inhibitors and radioligands, the glossary
 * terms and the medicines are owned elsewhere and are only supplemented here.
 */
export const PROSTATE_CANCER_ID = "prostate";
const PC = PROSTATE_CANCER_ID;
const MCRPC = "prostate-mcrpc";
const MHSPC = "prostate-mhspc";
