// ======================= PAPERS, PART B: THE LANDSCAPE COHORTS =======================
const papersB: PaperInput[] = [
  p({ id: SRC.tcga2015.paper, name: "The molecular taxonomy of primary prostate cancer",
    tldr: "Reading 333 prostate cancers removed by surgery sorted three quarters of them into seven groups, each defined by a single founder event, and showed that a quarter fit none of them.",
    summary: "A comprehensive molecular analysis of 333 primary prostate carcinomas as part of The Cancer Genome Atlas. Seventy-four per cent of the tumours fell into one of seven subtypes defined by specific gene fusions, ERG at 46%, ETV1 at 8%, ETV4 at 4% and FLI1 at 1%, or by mutations, SPOP at 11%, FOXA1 at 3% and IDH1 at 1%. Epigenetic profiles were substantially heterogeneous, including an IDH1-mutant subset with a methylator phenotype. Androgen receptor activity varied widely and in a subtype-specific way, with SPOP-mutant and FOXA1-mutant tumours having the highest levels of androgen receptor-induced transcripts. Twenty-five per cent of the cancers carried a presumed actionable lesion in the PI3K or MAPK pathways, and DNA repair genes were inactivated in 19%.",
    journal: "Cell", year: 2015, doi: "10.1016/j.cell.2015.10.025", pmid: "26544944", authors: "Cancer Genome Atlas Research Network.", paperType: "basic", participants: 333, changedPractice: false,
    findings: ["Seven subtypes covering 74% of tumours: ERG 46%, ETV1 8%, ETV4 4%, FLI1 1%, SPOP 11%, FOXA1 3%, IDH1 1%.", "SPOP-mutant and FOXA1-mutant tumours had the highest androgen receptor transcriptional output.", "A presumed actionable PI3K or MAPK lesion in 25%, DNA repair genes inactivated in 19%.", "An IDH1-mutant subset with a DNA methylator phenotype."],
    whatItMeans: "It is the reference map of the primary tumour and the source of the fusion-against-mutation taxonomy the field still uses. Its most quoted number is the 26% that fit no class, which is the honest measure of how much of this disease is still unexplained.",
    caveats: ["A surgical, mostly localised cohort, so it describes the disease that is cured far more often than the disease that kills.", "Multifocality means a single sampled focus may not represent the tumour that later metastasises.", "The subtypes have no treatment consequence today."],
    links: [link(SRC.tcga2015), { label: "PubMed", url: pubmed("26544944") }, CB_TCGA_PUB, CB_TCGA], cancers: [PC], targets: ["erg", "etv1", "spop", "foxa1", "idh", "pten", "tp53", "androgen-receptor"], pathways: ["prostate-cancer-signalling", "ar-signaling", "pi3k-akt-mtor", "ubiquitin-proteasome-system", "epigenetic-reprogramming"], terms: ["gene-fusion", "driver-mutation", "gleason-grade-group", "somatic-mutations-wxs-wgs"], technologies: ["wes-wgs", "rna-seq"], journals: ["cell"] }),
  p({ id: SRC.barbieri2012.paper, name: "Exome sequencing identifies recurrent SPOP, FOXA1 and MED12 mutations in prostate cancer",
    tldr: "Sequencing the genes of 112 prostate cancers found the disease's commonest point mutation in a gene nobody had linked to it, and showed those tumours are a separate kind that never carries the usual fusion.",
    summary: "The exomes of 112 prostate tumour and normal tissue pairs were sequenced. New recurrent mutations were identified in multiple genes including MED12 and FOXA1. SPOP was the most frequently mutated gene, with mutations involving the SPOP substrate-binding cleft in 6 to 15% of tumours across multiple independent cohorts. Prostate cancers with mutant SPOP lacked ETS family gene rearrangements and showed a distinct pattern of genomic alterations, so SPOP mutation appears to define a molecular subtype.",
    journal: "Nature Genetics", year: 2012, doi: "10.1038/ng.2279", pmid: "22610119", authors: "Barbieri CE, Baca SC, Lawrence MS, et al.", paperType: "basic", participants: 112, changedPractice: false,
    findings: ["SPOP the most frequently mutated gene, in 6 to 15% of tumours across independent cohorts.", "Mutations cluster in the substrate-binding cleft of the SPOP protein.", "SPOP-mutant tumours lack ETS rearrangements and carry their own copy-number pattern.", "New recurrent mutations in FOXA1 and MED12."],
    whatItMeans: "It established the fusion-negative side of the prostate cancer taxonomy and made SPOP the disease's signature point mutation, in a ubiquitin ligase adaptor rather than in a kinase, which is part of why prostate cancer has so few druggable drivers.",
    caveats: ["One hundred and twelve exomes, so rarer events were missed; the 1,013-exome reanalysis later found a long tail.", "No SPOP-directed medicine exists.", "Localised disease, so the mutation frequencies in metastatic disease are different."],
    links: [link(SRC.barbieri2012), { label: "PubMed", url: pubmed("22610119") }, CB_BROAD], cancers: [PC], targets: ["spop", "foxa1", "erg"], pathways: ["ubiquitin-proteasome-system", "prostate-cancer-signalling", "ar-signaling"], terms: ["driver-mutation", "gene-fusion", "somatic-mutations-wxs-wgs"], technologies: ["wes-wgs"], journals: ["nature-genetics"] }),
  p({ id: SRC.grasso2012.paper, name: "The mutational landscape of lethal castration-resistant prostate cancer",
    tldr: "Sequencing 50 prostate cancers taken at autopsy from men who had died of the disease showed the tumour keeps a single origin even after years of treatment, and found new mutations in the machinery that lets the androgen receptor work.",
    summary: "The exomes of 50 lethal, heavily pre-treated metastatic castration-resistant prostate cancers obtained at rapid autopsy, including three separate foci from one man, and 11 treatment-naive high-grade localised prostate cancers, were sequenced. Overall mutation rates were low even in heavily treated disease, at 2.00 per megabase, and the monoclonal origin of lethal castration-resistant disease was confirmed. Integrating exome copy-number analysis identified disruptions of CHD1 defining a subtype of ETS fusion-negative prostate cancer, and showed that ETS2, deleted in about a third of castration-resistant cancers commonly through TMPRSS2-ERG fusion, is also deregulated by mutation. Recurrent mutations were found in chromatin- and histone-modifying genes including MLL2, now KMT2D, mutated in 8.6%, and the MLL complex was shown to interact with the androgen receptor and to be required for receptor-mediated signalling. Novel recurrent FOXA1 mutations were found in 5 of 147 prostate cancers, 3.4%, and mutant FOXA1 repressed androgen signalling and increased tumour growth.",
    journal: "Nature", year: 2012, doi: "10.1038/nature11125", pmid: "22722839", authors: "Grasso CS, Wu YM, Robinson DR, et al.", paperType: "basic", participants: 61, changedPractice: false,
    findings: ["Low overall mutation rate of 2.00 per megabase even after heavy treatment, and confirmation of monoclonal origin.", "CHD1 disruption defining a subtype of ETS fusion-negative prostate cancer.", "KMT2D (MLL2) mutated in 8.6%, with the MLL complex required for androgen receptor signalling.", "FOXA1 mutations in 5 of 147 cancers, repressing androgen signalling and increasing growth."],
    whatItMeans: "It showed that the proteins mutated in lethal prostate cancer are the ones that physically partner the androgen receptor, which is why chromatin genes belong on an androgen receptor page rather than in a generic epigenetics list, and it gave the field the CHD1-deleted subtype.",
    caveats: ["Fifty rapid-autopsy cases is a small and extreme sample of lethal disease.", "Rapid autopsy cohorts are selected by consent and by geography.", "Copy-number inference from exome data is coarse compared with whole genomes."],
    links: [link(SRC.grasso2012), { label: "PubMed", url: pubmed("22722839") }, CB_MICH], cancers: [PC, MCRPC], targets: ["foxa1", "kmt2d", "erg", "androgen-receptor", "kmt2c"], pathways: ["ar-signaling", "epigenetic-reprogramming", "clonal-evolution", "prostate-cancer-signalling"], terms: ["driver-mutation", "gene-fusion", "castration-resistance", "somatic-mutations-wxs-wgs"], technologies: ["wes-wgs"], journals: ["nature"] }),
  p({ id: SRC.taylor2010.paper, name: "Integrative genomic profiling of human prostate cancer",
    tldr: "Profiling 218 prostate tumours on three platforms at once found a new oncogene in about a tenth of them and showed that counting copy-number changes separates high-risk from low-risk disease better than the microscope grade does.",
    summary: "Concordant assessment of DNA copy number, messenger RNA expression and focused exon resequencing in 218 prostate cancer tumours identified the nuclear receptor coactivator NCOA2 as an oncogene in approximately 11% of tumours. The androgen-driven TMPRSS2-ERG fusion was associated with a previously unrecognised prostate-specific deletion at chromosome 3p14 implicating FOXP1, RYBP and SHQ1 as potential cooperative tumour suppressors. DNA copy-number data from primary tumours defined clusters of low- and high-risk disease beyond what Gleason score achieved. The genomic and clinical outcome data were released as a public resource.",
    journal: "Cancer Cell", year: 2010, doi: "10.1016/j.ccr.2010.05.026", pmid: "20579941", authors: "Taylor BS, Schultz N, Hieronymus H, et al.", paperType: "basic", participants: 218, changedPractice: false,
    findings: ["NCOA2 identified as an oncogene in about 11% of prostate tumours.", "TMPRSS2-ERG associated with a prostate-specific 3p14 deletion implicating FOXP1, RYBP and SHQ1.", "Copy-number burden stratified risk beyond Gleason score."],
    whatItMeans: "It is the cohort that made copy-number burden a prognostic idea in prostate cancer, which later became the commercial genomic classifiers, and it is one of the first oncology datasets to have been released as a public resource in the form the field still uses.",
    caveats: ["Two hundred and eighteen tumours with targeted rather than whole-exome resequencing.", "The copy-number risk clusters were not prospectively validated as a test here.", "NCOA2 has no therapy."],
    links: [link(SRC.taylor2010), { label: "PubMed", url: pubmed("20579941") }], cancers: [PC], targets: ["ncoa2", "erg", "androgen-receptor"], pathways: ["ar-signaling", "chromosomal-instability", "prostate-cancer-signalling"], terms: ["copy-number-variation-term", "gene-fusion", "gleason-grade-group"], technologies: ["cgp"], journals: ["cancer-cell"] }),
  p({ id: SRC.robinson2015.paper, name: "Integrative clinical genomics of advanced prostate cancer",
    tldr: "The first prospective sequencing of bone and soft-tissue biopsies from 150 men with advanced prostate cancer found something potentially actionable in nearly nine out of ten, and found inherited repair-gene faults in one in twelve.",
    summary: "A multi-institutional clinical sequencing infrastructure carried out prospective whole-exome and transcriptome sequencing of bone or soft tissue tumour biopsies from 150 men with metastatic castration-resistant prostate cancer. Aberrations of AR, ETS genes, TP53 and PTEN were frequent, in 40 to 60% of cases, with TP53 and AR alterations enriched compared with primary prostate cancer. New genomic alterations were identified in PIK3CA and PIK3CB, in R-spondin, in BRAF and RAF1, in APC, in beta-catenin and in ZBTB16. Aberrations of BRCA2, BRCA1 and ATM were observed at substantially higher frequencies than in primary disease, 19.3% overall. Eighty-nine per cent of the men harboured a clinically actionable aberration, including 62.7% with aberrations in AR, 65% in other cancer-related genes, and 8% with actionable pathogenic germline alterations.",
    journal: "Cell", year: 2015, doi: "10.1016/j.cell.2015.05.001", pmid: "26000489", authors: "Robinson D, Van Allen EM, Wu YM, et al.", paperType: "basic", participants: 150, changedPractice: true,
    findings: ["AR, ETS, TP53 and PTEN aberrations in 40 to 60% of metastatic castration-resistant cases.", "BRCA2, BRCA1 and ATM aberrations in 19.3%, far above primary disease.", "Clinically actionable aberrations in 89% of men, including 8% with actionable pathogenic germline alterations.", "New alterations in PIK3CA/B, R-spondin, BRAF/RAF1, APC, beta-catenin and ZBTB16."],
    whatItMeans: "It proved that biopsying metastatic prostate cancer prospectively is feasible, including bone, and it produced the repair-gene frequency that led directly to the PARP inhibitor trials. It is also the origin of the widely quoted claim that most advanced prostate cancers carry something actionable, which needs reading carefully because most of that 89% is AR.",
    caveats: ["Actionable was defined generously, and an AR aberration is not actionable in the way a BRCA2 loss is.", "One hundred and fifty men at academic centres, so referral selection applies.", "Germline calls were incidental rather than the object of a consented germline test."],
    links: [link(SRC.robinson2015), { label: "PubMed", url: pubmed("26000489") }, CB_SU2C15], cancers: [PC, MCRPC], targets: ["androgen-receptor", "brca", "atm", "tp53", "pten", "pik3ca", "erg", "apc", "zbtb16"], pathways: ["ar-signaling", "homologous-recombination-repair", "pi3k-akt-mtor", "wnt", "prostate-cancer-signalling"], terms: ["castration-resistance", "germline-vs-somatic", "driver-mutation", "biopsy"], technologies: ["wes-wgs", "rna-seq", "cgp"], journals: ["cell"] }),
  p({ id: SRC.abida2019.paper, name: "Genomic correlates of clinical outcome in advanced prostate cancer",
    tldr: "Linking the genetics of 429 men with advanced prostate cancer to how long they lived showed that only one gene, RB1, predicted a worse outcome once everything else was accounted for.",
    summary: "Comprehensive genomic and transcriptomic analysis of 429 patients with metastatic castration-resistant prostate cancer was linked with longitudinal clinical outcomes, integrating whole-exome, transcriptome and histological analysis. For the 128 patients treated with a first-line next-generation androgen receptor signalling inhibitor, abiraterone or enzalutamide, the association of 18 recurrent DNA- and RNA-based alterations with clinical outcome was examined, including AR variant expression, AR transcriptional output and neuroendocrine expression signatures. Of these, only RB1 alteration was significantly associated with poor survival, whereas alterations in RB1, AR and TP53 were each associated with a shorter time on treatment with a receptor signalling inhibitor.",
    journal: "Proceedings of the National Academy of Sciences", year: 2019, doi: "10.1073/pnas.1902651116", pmid: "31061129", authors: "Abida W, Cyrta J, Heller G, et al.", paperType: "observational", participants: 429, changedPractice: false,
    findings: ["Only RB1 alteration was significantly associated with poor overall survival among 18 candidate markers.", "RB1, AR and TP53 alterations each associated with shorter time on a first receptor signalling inhibitor.", "A community resource pairing metastatic genomics with histology and longitudinal outcomes."],
    whatItMeans: "It is the most disciplined outcome analysis in this disease and its result is deflationary in a useful way: most of the alterations people quote as prognostic do not survive adjustment, and the one that does, RB1, is also the one that marks the route to neuroendocrine transformation.",
    caveats: ["Observational and not randomised, so the associations are prognostic rather than predictive.", "One hundred and twenty-eight men in the treatment-outcome subset.", "Academic referral centres, so the cohort is younger and fitter than the disease as a whole."],
    links: [link(SRC.abida2019), { label: "PubMed", url: pubmed("31061129") }, CB_SU2C19], cancers: [PC, MCRPC], targets: ["rb1", "androgen-receptor", "tp53"], pathways: ["ar-signaling", "p53-cell-cycle", "lineage-plasticity-neuroendocrine"], terms: ["castration-resistance", "resistance", "driver-mutation"], technologies: ["wes-wgs", "rna-seq"], journals: ["pnas"] }),
  p({ id: SRC.armenia2018.paper, name: "The long tail of oncogenic drivers in prostate cancer",
    tldr: "Reanalysing 1,013 prostate cancers the same way found 97 genes driving the disease, 70 of them new, and almost all of them mutated in fewer than three tumours in a hundred.",
    summary: "Exome sequencing data from 1,013 prostate cancers were aggregated and uniformly analysed. A new class of ETS fusion-negative tumours was identified and validated, defined by mutations in epigenetic regulators, alongside alterations in pathways not previously implicated in prostate cancer such as the spliceosome pathway. The incidence of significantly mutated genes followed a long-tail distribution, with many genes mutated in less than 3% of cases. Ninety-seven significantly mutated genes were identified in total, including 70 not previously implicated in prostate cancer, among them the ubiquitin ligase CUL3 and the transcription factor SPEN. Comparing primary and metastatic prostate cancer identified genomic markers that may inform risk stratification.",
    journal: "Nature Genetics", year: 2018, doi: "10.1038/s41588-018-0078-z", pmid: "29610475", authors: "Armenia J, Wankowicz SAM, Liu D, et al.", paperType: "basic", participants: 1013, changedPractice: false,
    findings: ["Ninety-seven significantly mutated genes, 70 of them new to prostate cancer.", "A new ETS fusion-negative class defined by mutations in epigenetic regulators.", "Alterations in the spliceosome pathway, not previously implicated.", "A long-tail distribution with many drivers below 3% prevalence."],
    whatItMeans: "It is the quantitative answer to why prostate cancer has so few targeted therapies. The common events are not druggable, the druggable ones are individually rare, and no trial can be powered on a driver present in 2% of men without an international basket.",
    caveats: ["Aggregating exomes from different studies means different capture kits and different pipelines even after uniform reanalysis.", "A mixture of primary and metastatic samples.", "Statistical significance of a mutated gene is not the same as a demonstrated driver function."],
    links: [link(SRC.armenia2018), { label: "PubMed", url: pubmed("29610475") }, CB_P1000], cancers: [PC, MCRPC], targets: ["spop", "foxa1", "erg", "kmt2c", "kmt2d"], pathways: ["prostate-cancer-signalling", "epigenetic-reprogramming", "rna-splicing", "ubiquitin-proteasome-system"], terms: ["driver-mutation", "gene-fusion", "somatic-mutations-wxs-wgs", "vus"], technologies: ["wes-wgs"], journals: ["nature-genetics"] }),
  p({ id: SRC.kumar2016.paper, name: "Substantial interindividual and limited intraindividual genomic diversity among tumours from men with metastatic prostate cancer",
    tldr: "Sequencing several metastases from the same man showed they are genetically much more alike than metastases from different men, so one good biopsy usually represents the rest.",
    summary: "Multiple tumours from men with disseminated prostate cancer were analysed by whole-exome sequencing, array comparative genomic hybridisation and RNA transcript profiling, and genomic diversity within and between individuals was compared. In contrast to the substantial heterogeneity between men, there was limited diversity among metastases within an individual: the number of somatic mutations, the burden of copy-number alterations and aberrations in known oncogenic drivers were all highly concordant, as were metrics of androgen receptor activity and cell-cycle activity. Androgen receptor activity was inversely associated with cell proliferation, while expression of Fanconi anaemia complex genes correlated with elevated cell-cycle progression, E2F1 expression and RB1 loss. Men with somatic aberrations in Fanconi anaemia complex genes or in ATM had significantly longer responses to carboplatin than men without DNA repair gene defects.",
    journal: "Nature Medicine", year: 2016, doi: "10.1038/nm.4053", pmid: "26928463", authors: "Kumar A, Coleman I, Morrissey C, et al.", paperType: "basic", changedPractice: false,
    findings: ["Limited genomic diversity among metastases within one man against substantial diversity between men.", "Concordant mutation counts, copy-number burden, driver aberrations, androgen receptor activity and cell-cycle activity across a man's metastases.", "Longer carboplatin response durations in men with Fanconi anaemia complex or ATM aberrations."],
    whatItMeans: "It is the reason a single metastatic biopsy is defensible in this disease, where in lung and bowel cancer heterogeneity makes one sample a gamble. The caveat is that it applies to driver alterations and not to the polyclonal resistance events that appear under treatment.",
    caveats: ["Rapid-autopsy and research-biopsy material, so the men are not a clinic population.", "Exceptions existed and the authors said so.", "The carboplatin association is retrospective and in small numbers."],
    links: [link(SRC.kumar2016), { label: "PubMed", url: pubmed("26928463") }, CB_FHCRC], cancers: [PC, MCRPC], targets: ["androgen-receptor", "atm", "rb1"], pathways: ["clonal-evolution", "homologous-recombination-repair", "ar-signaling"], terms: ["biopsy", "castration-resistance", "resistance"], technologies: ["wes-wgs", "rna-seq"], journals: ["nature-medicine"] }),
  p({ id: SRC.stopsack2020.paper, name: "Oncogenic genomic alterations, clinical phenotypes and outcomes in metastatic castration-sensitive prostate cancer",
    tldr: "Sequencing 424 men at the point their cancer had spread but before hormone treatment failed showed which genetic changes make castration resistance come sooner, and which make it come later.",
    summary: "Clinical-grade targeted tumour sequencing was performed in men with metastatic castration-sensitive prostate cancer at a tertiary referral centre, quantifying copy-number alterations and alterations in predefined oncogenic signalling pathways. Among 424 men, 213 had high-volume disease and 211 low-volume disease, 275 had de novo metastatic disease and 149 metastatic recurrence of earlier non-metastatic disease. Rates of castration resistance and of death were higher in high-volume disease, and high-volume tumours carried more copy-number alterations, with the NOTCH, cell-cycle and epigenetic modifier pathways ranking highest. De novo metastatic disease differed from metastatic recurrence in the prevalence of CDK12 alterations but had similar prognosis. Rates of castration resistance differed 1.5-fold to 5-fold according to alterations in AR, SPOP (in the inverse direction) and TP53 and to the cell-cycle, WNT (inverse) and MYC pathways, adjusting for disease volume; overall survival differed 2-fold to 4-fold by AR, SPOP (inverse), WNT (inverse) and cell-cycle alterations. PI3K pathway alterations carried no independent prognostic weight.",
    journal: "Clinical Cancer Research", year: 2020, doi: "10.1158/1078-0432.CCR-20-0168", pmid: "32220891", authors: "Stopsack KH, Nandakumar S, Wibmer AG, et al.", paperType: "observational", participants: 424, changedPractice: false,
    findings: ["AR and TP53 alterations and cell-cycle and MYC pathway alterations associated with faster castration resistance.", "SPOP and WNT alterations associated with slower castration resistance and longer survival.", "CDK12 alterations differed between de novo metastatic disease and metastatic recurrence.", "PI3K pathway alterations carried no independent prognostic weight after adjustment."],
    whatItMeans: "It fills the gap between the primary-tumour atlases and the castration-resistant series by describing the disease at the moment most treatment decisions are actually made, and it identifies SPOP as a favourable marker rather than a neutral one.",
    caveats: ["Eighty-eight per cent of the men were White, at a single tertiary centre.", "Targeted panel sequencing, so structural and non-coding events are invisible.", "Prognostic associations, not a basis for withholding or intensifying treatment."],
    links: [link(SRC.stopsack2020), { label: "PubMed", url: pubmed("32220891") }, CB_MCSPC], cancers: [PC, MHSPC], targets: ["androgen-receptor", "spop", "tp53", "cdk12", "apc"], pathways: ["ar-signaling", "p53-cell-cycle", "wnt", "myc", "cell-cycle-engine-cdks"], terms: ["castration-resistance", "mcrpc-mhspc", "driver-mutation"], technologies: ["cgp"], journals: ["clinical-cancer-research"] }),
  p({ id: SRC.stopsack2022.paper, name: "Differences in prostate cancer genomes by self-reported race",
    tldr: "Comparing the tumours of 2,069 men treated at one hospital found real genomic differences by race that survived adjusting for stage and PSA, including more of the chromosome change that carries the worst prognosis in Black men.",
    summary: "Among 2,069 men with prostate cancer with access to clinical-grade sequencing at the same cancer centre, 1,841 self-reported White, 63 Asian and 165 Black, the prevalence of tumour and germline alterations was assessed in driver genes previously reported to differ by race. Clinical characteristics including PSA, age at diagnosis and cancer stage at sample procurement differed by self-reported race, but most genomic differences persisted after adjustment. Tumours from Black men carried fewer PTEN mutations and more AR alterations than those from White men; tumours from Asian men carried more FOXA1 mutations and more ZFHX3 alterations. Despite fewer TP53 mutations, tumours from Black men had more aneuploidy, particularly gains of chromosome arm 8q, an adverse prognostic factor. Genetic ancestry was associated with similar tumour alterations to self-reported race but also with modifiable cancer risk factors, and community-level average income was associated with 8q gain after adjusting for race and ancestry.",
    journal: "Clinical Cancer Research", year: 2022, doi: "10.1158/1078-0432.CCR-21-2577", pmid: "34667026", authors: "Stopsack KH, Nandakumar S, Arora K, et al.", paperType: "observational", participants: 2069, changedPractice: false,
    findings: ["Fewer PTEN mutations and more AR alterations in tumours from Black men after adjustment.", "More FOXA1 mutations and ZFHX3 alterations in tumours from Asian men.", "More aneuploidy and specifically more 8q gain in tumours from Black men, despite fewer TP53 mutations.", "Community-level average income associated with 8q gain even after adjusting for race and genetic ancestry."],
    whatItMeans: "It separates two explanations that are usually run together. Some of the difference in prostate cancer outcomes by race is in the tumour genome and persists when access to the same centre is held constant, and some of it tracks with income rather than with ancestry, so equalising access alone would not eliminate the gap.",
    caveats: ["One hundred and sixty-five Black men and 63 Asian men, so the minority groups are small.", "A single centre whose patients have unusual access to sequencing.", "Self-reported race and genetic ancestry are different variables and the paper is careful not to conflate them; readers often do."],
    links: [link(SRC.stopsack2022), { label: "PubMed", url: pubmed("34667026") }, CB_MSK_RACE], cancers: [PC], targets: ["pten", "androgen-receptor", "foxa1", "zbtb16", "tp53"], pathways: ["chromosomal-instability", "ar-signaling", "prostate-cancer-signalling"], terms: ["copy-number-variation-term", "driver-mutation"], technologies: ["cgp"], journals: ["clinical-cancer-research"] }),
  p({ id: SRC.ren2018.paper, name: "Whole-genome and transcriptome sequencing of prostate cancer identifies new genetic alterations driving disease progression",
    tldr: "The first large genomic study of prostate cancer in Chinese men found the signature fusion that dominates Western series is uncommon, and a different deletion takes its place.",
    summary: "Whole-genome and transcriptome sequencing was performed on tumour and matched benign tissue from 65 treatment-naive Chinese prostate cancer patients, with targeted deep sequencing of 293 prostate cancer-relevant genes in a further 145 tumours. A high frequency of CHD1 deletion was associated with a low rate of TMPRSS2-ERG fusion and a relatively high proportion of mutations in genes upstream of the androgen receptor. Five putative clustered deleted tumour suppressor genes were identified, with experimental and clinical evidence that PCDH9, deleted or lost in about 23% of tumours, functions as a tumour suppressor with prognostic value. Axon guidance pathway genes were frequently deregulated, including gain or amplification of PLXNA1 in about 17% of tumours, and increased PLXNA1 expression promoted tumour growth and independently predicted biochemical recurrence, metastasis and poor survival in multi-institutional cohorts.",
    journal: "European Urology", year: 2018, doi: "10.1016/j.eururo.2017.08.027", pmid: "28927585", authors: "Ren S, Wei GH, Liu D, et al.", paperType: "basic", participants: 210, changedPractice: false,
    findings: ["High CHD1 deletion frequency with a low TMPRSS2-ERG fusion rate in Chinese patients.", "PCDH9 deleted or lost in about 23% of tumours and shown to be a tumour suppressor with prognostic value.", "PLXNA1 gained or amplified in about 17%, predicting recurrence, metastasis and poor survival."],
    whatItMeans: "It is the reason a prostate cancer fusion frequency quoted without an ancestry is unsafe. In this cohort the founder event that defines almost half of Western tumours is uncommon, and the fusion-negative, CHD1-deleted route dominates instead.",
    caveats: ["Sixty-five whole genomes with a 145-tumour targeted validation set.", "Treatment-naive disease, so it describes the primary tumour.", "PCDH9 and PLXNA1 have no therapy and have not been widely replicated."],
    links: [link(SRC.ren2018), { label: "PubMed", url: pubmed("28927585") }, CB_SMMU], cancers: [PC], targets: ["erg", "tmprss2", "androgen-receptor"], pathways: ["prostate-cancer-signalling", "ar-signaling", "chromosomal-instability"], terms: ["gene-fusion", "copy-number-variation-term", "driver-mutation"], technologies: ["wes-wgs", "rna-seq"], journals: ["european-urology"] }),
  p({ id: SRC.mateo2020.paper, name: "Genomics of lethal prostate cancer at diagnosis and castration resistance",
    tldr: "Sequencing the original diagnostic biopsies of men who later died of prostate cancer showed the dangerous changes were already there at the start, years before the disease became resistant.",
    summary: "Genomic aberrations were studied in primary prostate cancer diagnostic biopsies from men who went on to develop metastatic castration-resistant prostate cancer, with matching same-patient diagnostic and castration-resistant biopsies for a subset. Four hundred and seventy treatment-naive diagnostic biopsies were profiled by targeted and low-pass whole-genome sequencing, with 61 matched castration-resistant biopsies. TP53 was altered in 27% and PTEN in 12%, with DNA damage repair gene defects in BRCA2 at 7%, CDK12 at 5% and ATM at 4%. TP53, BRCA2 and CDK12 mutations were markedly more common than in the TCGA primary cohort. Men whose primary tumour carried RB1 loss had a worse prognosis. Among the 61 men with matched biopsies, differences were identified in AR, TP53, RB1 and PI3K or AKT mutational status between the two time points.",
    journal: "Journal of Clinical Investigation", year: 2020, doi: "10.1172/JCI132031", pmid: "31874108", authors: "Mateo J, Seed G, Bertan C, et al.", paperType: "observational", participants: 470, changedPractice: false,
    findings: ["TP53 altered in 27% and PTEN in 12% of diagnostic biopsies from men who later developed castration-resistant disease.", "BRCA2 7%, CDK12 5% and ATM 4% at diagnosis, similar to the prevalence in castration-resistant disease.", "RB1 loss in the primary tumour associated with worse prognosis.", "AR, TP53, RB1 and PI3K/AKT status differed between paired diagnostic and castration-resistant samples."],
    whatItMeans: "It splits the alterations into two groups with different practical meanings. The repair defects are present at diagnosis at close to their castration-resistant prevalence, so testing early is worthwhile; AR, TP53 and RB1 changes accumulate later, so a diagnostic sample does not answer questions about the disease in front of you at relapse.",
    caveats: ["Selected by outcome: these are the primaries of men who went on to die of the disease, so the prevalences are not those of prostate cancer generally.", "Targeted and low-pass sequencing on archival diagnostic biopsies, which are small and often decades old.", "Sixty-one matched pairs is a small number on which to describe evolution."],
    links: [link(SRC.mateo2020), { label: "PubMed", url: pubmed("31874108") }], cancers: [PC, MCRPC], targets: ["tp53", "pten", "brca", "cdk12", "atm", "rb1", "androgen-receptor"], pathways: ["homologous-recombination-repair", "p53-cell-cycle", "ar-signaling", "pi3k-akt-mtor", "clonal-evolution"], terms: ["biopsy", "castration-resistance", "driver-mutation"], technologies: ["cgp", "wes-wgs"], journals: ["jci"] }),
];

// ======================= PAPERS, PART C: DNA REPAIR, PI3K AND THE FUSIONS =======================
const papersC: PaperInput[] = [
  p({ id: SRC.pritchard2016.paper, name: "Inherited DNA-repair gene mutations in men with metastatic prostate cancer",
    tldr: "Testing 692 men with advanced prostate cancer, whatever their family history, found an inherited DNA repair fault in about one in eight, and family history did not predict who had one.",
    summary: "Six hundred and ninety-two men with documented metastatic prostate cancer, unselected for family history of cancer or age at diagnosis, were recruited, and germline DNA was assessed for mutations in 20 DNA repair genes associated with autosomal dominant cancer predisposition using multiplex sequencing assays. Eighty-four presumed deleterious germline mutations were identified in 82 men, 11.8%, across 16 genes, including BRCA2 in 37 men (5.3%), ATM in 11 (1.6%), CHEK2 in 10 (1.9% of the 534 men with data), BRCA1 in 6 (0.9%), RAD51D in 3 (0.4%) and PALB2 in 3 (0.4%). Mutation frequencies did not differ according to whether a family history of prostate cancer was present or according to age at diagnosis. The overall frequency significantly exceeded the 4.6% among 499 men with localised prostate cancer, including high-risk disease, and the 2.7% among 53,105 people in the Exome Aggregation Consortium without a known cancer diagnosis.",
    journal: "New England Journal of Medicine", year: 2016, doi: "10.1056/NEJMoa1603144", pmid: "27433846", authors: "Pritchard CC, Mateo J, Walsh MF, et al.", paperType: "observational", participants: 692, changedPractice: true,
    findings: ["Germline DNA repair mutations in 82 of 692 men with metastatic prostate cancer, 11.8%, across 16 genes.", "BRCA2 5.3%, ATM 1.6%, CHEK2 1.9%, BRCA1 0.9%, RAD51D 0.4%, PALB2 0.4%.", "No difference by family history of prostate cancer or by age at diagnosis.", "Significantly higher than the 4.6% in localised disease and the 2.7% population background."],
    whatItMeans: "This is the study that made germline testing standard for metastatic prostate cancer. Its decisive result is the null one: a family history question cannot select who to test, so the test has to be offered to everyone with metastatic disease. It also changes the conversation with a man's sons and daughters.",
    caveats: ["Recruited from academic and registry sources, so not a pure population sample.", "Twenty genes, so mutations outside that panel were not counted.", "Prevalence in men of non-European ancestry is under-described by this and by most later series."],
    links: [link(SRC.pritchard2016), { label: "PubMed", url: pubmed("27433846") }], cancers: [PC, MCRPC], targets: ["brca", "atm", "chek2", "palb2", "rad51d"], pathways: ["homologous-recombination-repair", "ddr"], terms: ["germline-vs-somatic", "gbrca-mutation", "hrd", "lynch-syndrome"], technologies: ["germline-testing", "cgp"], journals: ["nejm"] }),
  p({ id: SRC.nicolosi2019.paper, name: "Prevalence of germline variants in prostate cancer and implications for current genetic testing guidelines",
    tldr: "Testing 3,607 men with prostate cancer on a broad gene panel found something inheritable in one in six, and more than a third of them would not have been offered the test under the guidelines then in force.",
    summary: "A cross-sectional study of 3,607 men with a personal history of prostate cancer who underwent germline genetic testing between 2013 and 2018, unselected for family history, stage of disease or age at diagnosis, at an accredited diagnostic laboratory. Six hundred and twenty men, 17.2%, had a positive result, defined as a pathogenic, likely pathogenic or increased-risk variant, and only 30.7% of those were in BRCA1 or BRCA2. Positive variants in HOXB13, a gene associated only with prostate cancer risk, were identified in 30 patients, 4.5% of those with a positive result. DNA mismatch repair variants with substantial known therapeutic implications were detected in 1.74% of the total population tested. Examination of self-reported family histories indicated that 229 men with positive variants, 37%, would not have been approved for genetic testing under the National Comprehensive Cancer Network genetic and familial breast and ovarian guidelines then applying to prostate cancer.",
    journal: "JAMA Oncology", year: 2019, doi: "10.1001/jamaoncol.2018.6760", pmid: "30730552", authors: "Nicolosi P, Ledet E, Yang S, et al.", paperType: "observational", participants: 3607, changedPractice: true,
    findings: ["Positive germline variants in 620 of 3,607 men, 17.2%, on a broad panel.", "Only 30.7% of positives were in BRCA1 or BRCA2.", "Mismatch repair variants with therapeutic implications in 1.74% of all men tested.", "Thirty-seven per cent of men with a positive result would not have qualified for testing under the guideline in force."],
    whatItMeans: "It is the second half of the argument for unselected germline testing, and it widens the target beyond BRCA: two thirds of the actionable inherited findings in prostate cancer are in other genes, including the mismatch repair genes that open a checkpoint inhibitor route.",
    caveats: ["A referral cohort tested at a commercial laboratory, so ascertainment is not random and the 17.2% is higher than a population figure would be.", "Increased-risk variants were counted alongside pathogenic ones.", "Family histories were self-reported."],
    links: [link(SRC.nicolosi2019), { label: "PubMed", url: pubmed("30730552") }], cancers: [PC], targets: ["brca", "atm", "chek2", "msh2", "mlh1"], pathways: ["homologous-recombination-repair", "mismatch-repair-msi", "ddr"], terms: ["germline-vs-somatic", "gbrca-mutation", "lynch-syndrome", "msi"], technologies: ["germline-testing"], journals: ["jama-oncology"] }),
  p({ id: SRC.castro2013.paper, name: "Germline BRCA mutations are associated with higher risk of nodal involvement, distant metastasis and poor survival outcomes in prostate cancer",
    tldr: "Comparing 79 men who inherited a BRCA fault with 1,940 who did not showed the carriers' cancers were higher grade, more often spread at diagnosis, and shortened life by years.",
    summary: "The tumour features and outcomes of 2,019 men with prostate cancer were analysed, 18 BRCA1 carriers, 61 BRCA2 carriers and 1,940 non-carriers. Prostate cancers in germline BRCA1 or BRCA2 carriers were more often Gleason 8 or higher, T3 or T4 stage, node-positive and metastatic at diagnosis. Cause-specific survival was significantly longer in non-carriers, 15.7 against 8.6 years, with a multivariable hazard ratio of 1.8. For localised disease at presentation, five-year cause-specific survival was 96% in non-carriers against 82% in carriers and five-year metastasis-free survival 93% against 77%. Subgroup analyses confirmed the poor outcomes in BRCA2 carriers, while the role of BRCA1 could not be defined because of the limited size of that subgroup.",
    journal: "Journal of Clinical Oncology", year: 2013, doi: "10.1200/JCO.2012.43.1882", pmid: "23569316", authors: "Castro E, Goh C, Olmos D, et al.", paperType: "observational", participants: 2019, changedPractice: true,
    findings: ["Carriers more often Gleason 8 or above, T3/T4, node-positive and metastatic at diagnosis.", "Cause-specific survival 15.7 years in non-carriers against 8.6 years in carriers, hazard ratio 1.8.", "Five-year cause-specific survival in localised disease 96% against 82%, metastasis-free survival 93% against 77%.", "The effect was confirmed for BRCA2; BRCA1 could not be resolved with 18 carriers."],
    whatItMeans: "It established that an inherited BRCA2 mutation changes the disease and not only the treatment options, which is why a carrier's localised disease is generally treated more intensively and watched more closely rather than put on surveillance.",
    caveats: ["These are cohort figures and not a personal prognosis.", "Predates PARP inhibitors, hormone intensification in castration-sensitive disease and PSMA PET staging, all of which change outcomes.", "Carriers were identified through family-cancer programmes, which selects for stronger family histories."],
    links: [link(SRC.castro2013), { label: "PubMed", url: pubmed("23569316") }], cancers: [PC], targets: ["brca"], pathways: ["homologous-recombination-repair", "ddr"], terms: ["germline-vs-somatic", "gbrca-mutation", "gleason-grade-group", "hrd"], technologies: ["germline-testing"], journals: ["jco"] }),
  p({ id: SRC.isaacssonVelho2018.paper, name: "Intraductal and ductal histology and lymphovascular invasion are associated with germline DNA-repair gene mutations in prostate cancer",
    tldr: "Among 150 men tested regardless of family history, the ones with an inherited repair fault were four times as likely to have a particular growth pattern on their pathology report.",
    summary: "One hundred and fifty consecutive unselected patients with recurrent or metastatic prostate cancer were offered germline genetic testing by a single oncologist using a clinical-grade 30-gene saliva assay. Pathogenic mutations were identified in 21 men, 14%: 9 in BRCA2, 3 in ATM, 3 in CHEK2 and 2 in BRCA1. There were no associations between germline mutation and age, tumour stage, Gleason sum or family history. Mutation-positive men had lower median PSA at diagnosis, 5.5 against 8.6 ng/mL, and distinctive pathological features: intraductal or ductal histology in 48% against 12%, and lymphovascular invasion in 52% against 14%. Forty-four per cent of the men with a positive germline test would not have been offered genetic screening under the National Comprehensive Cancer Network guidelines then in force.",
    journal: "The Prostate", year: 2018, doi: "10.1002/pros.23484", pmid: "29368341", authors: "Isaacsson Velho P, Silberstein JL, Markowski MC, et al.", paperType: "observational", participants: 150, changedPractice: false,
    findings: ["Pathogenic germline mutations in 21 of 150 men, 14%; BRCA2 in 9, ATM in 3, CHEK2 in 3, BRCA1 in 2.", "Intraductal or ductal histology in 48% of carriers against 12% of non-carriers.", "Lymphovascular invasion in 52% against 14%.", "No association with age, stage, Gleason sum or family history; 44% of carriers would not have qualified for testing."],
    whatItMeans: "It links a line on a UK pathology report to a question about a family. Intraductal carcinoma is a reportable item in the current dataset, and its presence is a practical prompt to check that germline testing has actually been offered rather than assumed.",
    caveats: ["One hundred and fifty consecutive patients of a single oncologist, so referral patterns shape it.", "Retrospective pathology review.", "Neither finding is sensitive enough to select who is tested; the case for unselected testing stands."],
    links: [link(SRC.isaacssonVelho2018), { label: "PubMed", url: pubmed("29368341") }], cancers: [PC, MCRPC], targets: ["brca", "atm", "chek2"], pathways: ["homologous-recombination-repair", "ddr"], terms: ["germline-vs-somatic", "gbrca-mutation", "hrd", "intraductal-carcinoma-prostate", "cribriform-prostate-cancer"], technologies: ["germline-testing", "histopathology-ihc"] }),
  p({ id: SRC.taylor2017.paper, name: "Germline BRCA2 mutations drive prostate cancers with distinct evolutionary trajectories",
    tldr: "Reading the whole genomes of localised prostate cancers from 14 men who had inherited a BRCA2 fault found tumours that already looked like advanced disease while still confined to the prostate.",
    summary: "The genomes and methylomes of localised prostate cancer from 14 carriers of deleterious germline BRCA2 mutations were profiled. BRCA2-mutant prostate cancers showed increased genomic instability and a mutational profile that more closely resembled metastatic than localised disease. They showed genomic and epigenomic dysregulation of the MED12L and MED12 axis, which is frequently dysregulated in metastatic castration-resistant prostate cancer, and this dysregulation was enriched in BRCA2-mutant tumours containing intraductal carcinoma. Microdissection and sequencing of intraductal carcinoma and the juxtaposed adjacent non-intraductal invasive carcinoma in 10 patients demonstrated a common ancestor to both histopathologies.",
    journal: "Nature Communications", year: 2017, doi: "10.1038/ncomms13671", pmid: "28067867", authors: "Taylor RA, Fraser M, Livingstone J, et al.", paperType: "basic", participants: 14, changedPractice: false,
    findings: ["Localised BRCA2-mutant prostate cancers showed greater genomic instability and a metastatic-like mutational profile.", "Dysregulation of the MED12L and MED12 axis, enriched in tumours containing intraductal carcinoma.", "Intraductal carcinoma and the adjacent invasive carcinoma share a common ancestor on microdissection of 10 cases."],
    whatItMeans: "It supplies the biological reason for treating a BRCA2 carrier's localised disease aggressively rather than watching it, and it settles a long-standing pathology question by showing that intraductal carcinoma and the adjacent invasive tumour are the same clone rather than two separate processes.",
    caveats: ["Fourteen genomes, so gene-level claims rest on very small numbers.", "Localised disease from carriers identified through genetics services.", "MED12L has no therapeutic consequence."],
    links: [link(SRC.taylor2017), { label: "PubMed", url: pubmed("28067867") }], cancers: [PC], targets: ["brca"], pathways: ["homologous-recombination-repair", "chromosomal-instability", "clonal-evolution"], terms: ["germline-vs-somatic", "gbrca-mutation", "hrd", "intraductal-carcinoma-prostate"], technologies: ["wes-wgs"], journals: ["nature-communications"] }),
  p({ id: SRC.quigley2017.paper, name: "Analysis of circulating cell-free DNA identifies multiclonal heterogeneity of BRCA2 reversion mutations associated with resistance to PARP inhibitors",
    tldr: "When PARP inhibitors stop working in prostate cancer, the tumour has repaired the broken gene, and a blood test shows it has done so in several different ways at once.",
    summary: "About 20% of metastatic prostate cancers carry mutations in genes required for DNA repair by homologous recombination, such as BRCA2, and those defects confer synthetic lethality to PARP inhibitors. In ovarian and breast cancer, olaparib resistance has been associated with restoration of homologous recombination, including by BRCA2 mutation reversion. This study identified BRCA2 reversion mutations associated with olaparib and talazoparib resistance in patients with prostate cancer. Analysis of circulating cell-free DNA revealed reversion mutation heterogeneity that was not discernible from a single solid-tumour biopsy, and suggested that cell-free DNA can be used to monitor for the emergence of PARP inhibitor resistance.",
    journal: "Cancer Discovery", year: 2017, doi: "10.1158/2159-8290.CD-17-0146", pmid: "28450426", authors: "Quigley D, Alumkal JJ, Wyatt AW, et al.", paperType: "translational", changedPractice: false,
    findings: ["BRCA2 reversion mutations identified in men with prostate cancer resistant to olaparib and to talazoparib.", "Resistance was highly multiclonal, with several independent restoring events.", "Cell-free DNA revealed heterogeneity a single solid-tumour biopsy could not show."],
    whatItMeans: "It establishes that PARP inhibitor resistance in prostate cancer is a restored repair pathway rather than a bypass, which is why platinum and PARP inhibitors lose activity together, and it is the argument for sampling plasma rather than one lesion at progression.",
    caveats: ["A small series of patients, published as a brief report.", "No licensed assay reports reversion mutations.", "Reversion is one mechanism among several and its frequency in prostate cancer has not been counted prospectively."],
    links: [link(SRC.quigley2017), { label: "PubMed", url: pubmed("28450426") }], cancers: [PC, MCRPC], targets: ["brca", "parp"], pathways: ["homologous-recombination-repair", "base-excision-repair-parp", "synthetic-lethality-map", "resistance-routes-map"], terms: ["brca-reversion-mutations", "resistance", "ctdna", "cfdna", "hrd"], technologies: ["liquid-biopsy"], journals: ["cancer-discovery"] }),
  p({ id: SRC.abidaTriton2020.paper, name: "Rucaparib in men with metastatic castration-resistant prostate cancer harbouring a BRCA1 or BRCA2 gene alteration",
    tldr: "In 115 men whose prostate cancer carried a BRCA fault, a PARP inhibitor shrank measurable tumour in about half and halved PSA in more than half.",
    summary: "TRITON2 enrolled men who had progressed after one to two lines of next-generation androgen receptor-directed therapy and one taxane-based chemotherapy for metastatic castration-resistant prostate cancer, and treated them with rucaparib 600 mg twice daily. The efficacy and safety populations included 115 men with a deleterious BRCA alteration with or without measurable disease. Confirmed objective response rates were 43.5% by independent radiology review, 27 of 62 men with measurable disease, and 50.8% by investigator assessment, 33 of 65. The confirmed PSA response rate, a fall of at least half, was 54.8%, 63 of 115. Response rates were similar for germline and somatic alterations and for BRCA1 and BRCA2 alterations, while a higher PSA response rate was observed with BRCA2. The most frequent grade 3 or higher treatment-emergent adverse event was anaemia, in 29 of 115 men, 25.2%.",
    journal: "Journal of Clinical Oncology", year: 2020, doi: "10.1200/JCO.20.01035", pmid: "32795228", authors: "Abida W, Patnaik A, Campbell D, et al.", paperType: "rct", participants: 115, changedPractice: true,
    findings: ["Confirmed objective response 43.5% by independent review in men with measurable disease.", "Confirmed PSA response 54.8% across all 115 men.", "Similar responses for germline and somatic alterations and for BRCA1 and BRCA2, with higher PSA responses in BRCA2.", "Grade 3 or higher anaemia in 25.2%."],
    whatItMeans: "It is the evidence behind the narrowest of the four prostate PARP inhibitor eligibility lists, and its germline-against-somatic result matters practically: a somatic BRCA alteration found on a tumour panel qualifies a man for the drug just as an inherited one does.",
    caveats: ["A single-arm phase 2 study, so the response rates have no randomised comparator.", "BRCA-altered men only, which is why it says nothing about the wider repair-gene lists.", "Anaemia at this rate matters in a population that is often already anaemic from bone disease and androgen deprivation."],
    links: [link(SRC.abidaTriton2020), { label: "PubMed", url: pubmed("32795228") }, { label: "RUBRACA prescribing information (DailyMed)", url: LABEL.rubraca }], cancers: [PC, MCRPC], targets: ["brca", "parp"], drugs: ["rucaparib"], pathways: ["homologous-recombination-repair", "base-excision-repair-parp", "synthetic-lethality-map"], terms: ["germline-vs-somatic", "gbrca-mutation", "psa50", "hrd"], technologies: ["parp-inhibitor", "cgp"], journals: ["jco"] }),
  p({ id: SRC.jensen2021.paper, name: "Association of clonal haematopoiesis in DNA repair genes with prostate cancer plasma cell-free DNA testing interference",
    tldr: "In one man in ten with advanced prostate cancer, a DNA repair fault found in a blood test came from his bone marrow rather than from his cancer, which could send him to the wrong drug.",
    summary: "A case series of 69 men with advanced prostate cancer, metastatic or with rising PSA after localised therapy, who had cell-free DNA variant testing with a large next-generation sequencing panel. To determine the source of variants in plasma, paired cell-free DNA and whole blood control samples were tested. Clonal haematopoiesis variants at 2% or more variant fraction were detected in cell-free DNA from 13 of the 69 men, 19%. Seven men, 10%, had clonal haematopoiesis variants in DNA repair genes used to determine PARP inhibitor candidacy, including ATM in 5, BRCA2 in 1 and CHEK2 in 1. Overall, clonal haematopoiesis variants accounted for almost half of the somatic DNA repair gene variants detected. Variants correlated exponentially with older age, and could be distinguished from prostate cancer variants using a paired whole blood control.",
    journal: "JAMA Oncology", year: 2021, doi: "10.1001/jamaoncol.2020.5161", pmid: "33151258", authors: "Jensen K, Konnick EQ, Schweizer MT, et al.", paperType: "observational", participants: 69, changedPractice: true,
    findings: ["Clonal haematopoiesis variants at 2% or more in plasma from 13 of 69 men, 19%.", "Seven men, 10%, had such a variant in a gene used to decide PARP inhibitor candidacy, most often ATM.", "Clonal haematopoiesis accounted for almost half of all somatic DNA repair variants detected in plasma.", "A paired whole blood control distinguishes them."],
    whatItMeans: "It identifies a way that a good test produces a wrong answer, and it names the fix. Any plasma repair-gene result used to decide on a PARP inhibitor should be run with a paired blood control, or an older man may be treated for a marrow clone rather than for his prostate cancer.",
    caveats: ["Sixty-nine men at one academic reference laboratory.", "A 2% variant fraction threshold is a choice, and lower-level interference will be commoner still.", "It does not quantify how often this has changed treatment in practice."],
    links: [link(SRC.jensen2021), { label: "PubMed", url: pubmed("33151258") }], cancers: [PC, MCRPC], targets: ["atm", "brca", "chek2"], pathways: ["homologous-recombination-repair", "clonal-haematopoiesis"], terms: ["ctdna", "cfdna", "germline-vs-somatic", "vus"], technologies: ["liquid-biopsy", "cgp"], journals: ["jama-oncology"] }),
  p({ id: SRC.carver2011.paper, name: "Reciprocal feedback regulation of PI3K and androgen receptor signalling in PTEN-deficient prostate cancer",
    tldr: "Two growth pathways in prostate cancer prop each other up: block one and the other switches on, which is why single drugs fail and the pair has to be blocked together.",
    summary: "Androgen receptor transcriptional output is decreased in human and murine prostate tumours with PTEN deletion, and PI3K pathway inhibition activates androgen receptor signalling by relieving feedback inhibition of the HER kinases. Conversely, androgen receptor inhibition activates AKT signalling by reducing levels of the AKT phosphatase PHLPP. The two oncogenic pathways therefore cross-regulate each other by reciprocal feedback, and inhibiting one activates the other, maintaining tumour cell survival. Combined pharmacological inhibition of PI3K and androgen receptor signalling caused near-complete prostate cancer regressions in a Pten-deficient murine prostate cancer model and in human prostate cancer xenografts.",
    journal: "Cancer Cell", year: 2011, doi: "10.1016/j.ccr.2011.04.008", pmid: "21575859", authors: "Carver BS, Chapinski C, Wongvipat J, et al.", paperType: "basic", changedPractice: false,
    findings: ["Androgen receptor output is reduced in PTEN-deleted prostate tumours.", "PI3K inhibition reactivates androgen receptor signalling by relieving feedback on the HER kinases.", "Androgen receptor inhibition activates AKT by reducing the phosphatase PHLPP.", "Combined inhibition produced near-complete regressions in Pten-deficient models and xenografts."],
    whatItMeans: "It is the reason every prostate PI3K or AKT trial gives the drug with abiraterone rather than alone, and the reason PTEN loss is used to select for those combinations rather than as a general prognostic marker.",
    caveats: ["Mouse models and xenografts; the human confirmation is the randomised trial, which met only one of its two co-primary endpoints.", "The feedback is described for PTEN-deficient disease and may not generalise.", "Toxicity of dual blockade in men has proved a limiting factor the models did not predict."],
    links: [link(SRC.carver2011), { label: "PubMed", url: pubmed("21575859") }], cancers: [PC, MCRPC], targets: ["pten", "akt", "androgen-receptor", "pik3ca"], pathways: ["pi3k-akt-mtor", "ar-signaling", "rtk-activation", "resistance-routes-map"], terms: ["resistance", "castration-resistance"], journals: ["cancer-cell"] }),
  p({ id: SRC.ferraldeschi2015.paper, name: "PTEN protein loss and clinical outcome from castration-resistant prostate cancer treated with abiraterone acetate",
    tldr: "Staining tumour samples from 144 men showed that the 40% who had lost a particular protein lived about seven months less on abiraterone.",
    summary: "Men who had received abiraterone and had hormone-sensitive or castration-resistant prostate cancer tissue available for PTEN immunohistochemistry were identified retrospectively, with overall survival from the start of abiraterone as the primary endpoint. One hundred and forty-four men who had received abiraterone after docetaxel had available tumour tissue. Loss of PTEN expression was observed in 40%. Matched hormone-sensitive and castration-resistant tumour biopsies were available for 41 men, and PTEN status in castration-resistant tissue matched the hormone-sensitive tissue in 86% of those cases. Loss of PTEN expression was associated with shorter median overall survival, 14 against 21 months, hazard ratio 1.75, and shorter median duration of abiraterone treatment, 24 against 28 weeks, hazard ratio 1.6. PTEN protein loss, high lactate dehydrogenase and visceral metastases were independent prognostic factors on multivariable analysis.",
    journal: "European Urology", year: 2015, doi: "10.1016/j.eururo.2014.10.027", pmid: "25454616", authors: "Ferraldeschi R, Nava Rodrigues D, Riisnaes R, et al.", paperType: "observational", participants: 144, changedPractice: false,
    findings: ["PTEN protein loss in 40% of 144 men treated with abiraterone after docetaxel.", "Median overall survival 14 against 21 months with PTEN loss, hazard ratio 1.75.", "PTEN status concordant between hormone-sensitive and castration-resistant biopsies in 86% of 41 paired cases.", "PTEN loss an independent prognostic factor alongside lactate dehydrogenase and visceral disease."],
    whatItMeans: "It made PTEN a protein test rather than a genomic one in this disease, and the concordance between early and late biopsies is the practical point: the diagnostic block usually answers the question, so a fresh biopsy is not needed to make this call.",
    caveats: ["Retrospective and single-institution, in men treated after docetaxel.", "Immunohistochemistry for PTEN is notoriously assay-dependent, which is why the phase 3 trial specified a single validated assay.", "Prognostic, and it does not by itself say abiraterone should be withheld."],
    links: [link(SRC.ferraldeschi2015), { label: "PubMed", url: pubmed("25454616") }], cancers: [PC, MCRPC], targets: ["pten", "akt"], drugs: ["abiraterone"], pathways: ["pi3k-akt-mtor", "ar-signaling"], terms: ["ihc", "castration-resistance", "resistance"], technologies: ["histopathology-ihc"], journals: ["european-urology"] }),
  p({ id: SRC.sweeney2021.paper, name: "IPATential150: ipatasertib plus abiraterone and prednisolone in metastatic castration-resistant prostate cancer",
    tldr: "Adding an AKT-blocking tablet to abiraterone delayed progression in the half of men who had lost PTEN, but at a considerable cost in side effects.",
    summary: "A randomised, double-blind phase 3 trial at 200 sites in 26 countries in men with previously untreated asymptomatic or mildly symptomatic metastatic castration-resistant prostate cancer with progressive disease. Of 1,611 men screened, 1,101 were enrolled and randomised to ipatasertib 400 mg daily with abiraterone and prednisolone or to placebo with abiraterone and prednisolone, stratified by prior taxane, type of progression, visceral metastasis and tumour PTEN-loss status by immunohistochemistry. In the 521 men, 47%, whose tumours showed PTEN loss by immunohistochemistry, median radiographic progression-free survival was 16.5 months with placebo and 18.5 months with ipatasertib, hazard ratio 0.77, significant at the prespecified alpha. In the intention-to-treat population the difference was 16.6 against 19.2 months, hazard ratio 0.84, not significant at its alpha. Grade 3 or higher adverse events occurred in 39% of the placebo group and 70% of the ipatasertib group, with discontinuation for adverse events in 5% against 21%.",
    journal: "Lancet", year: 2021, doi: "10.1016/S0140-6736(21)00580-8", pmid: "34246347", authors: "Sweeney C, Bracarda S, Sternberg CN, et al.", paperType: "rct", participants: 1101, changedPractice: false,
    findings: ["PTEN loss by immunohistochemistry in 521 of 1,101 men, 47%.", "Radiographic progression-free survival 18.5 against 16.5 months in the PTEN-loss population, hazard ratio 0.77.", "No significant difference in the intention-to-treat population at its prespecified alpha.", "Grade 3 or higher adverse events in 70% against 39%, with discontinuation in 21% against 5%."],
    whatItMeans: "It is the prospective test of the PI3K and androgen receptor feedback hypothesis in men, and it shows both halves of the answer: the biomarker-selected population benefits, and the benefit is small enough that the toxicity has to be weighed honestly.",
    caveats: ["A two-month median difference in radiographic progression-free survival, with overall survival not demonstrated here.", "PTEN loss was defined by one immunohistochemistry assay; a different assay would define a different population.", "One man in five stopped ipatasertib because of side effects."],
    links: [link(SRC.sweeney2021), { label: "PubMed", url: pubmed("34246347") }], cancers: [PC, MCRPC], targets: ["pten", "akt", "androgen-receptor"], drugs: ["abiraterone", "ipatasertib"], pathways: ["pi3k-akt-mtor", "ar-signaling"], terms: ["ihc", "castration-resistance"], technologies: ["histopathology-ihc"], journals: ["lancet"] }),
  p({ id: SRC.tomlins2005.paper, name: "Recurrent fusion of TMPRSS2 and ETS transcription factor genes in prostate cancer",
    tldr: "Looking for genes switched on far too strongly in a few tumours led to the discovery that half of all prostate cancers carry a fused gene, the first such fusion found in a common cancer.",
    summary: "A bioinformatics approach was used to discover candidate oncogenic chromosomal aberrations on the basis of outlier gene expression. Two ETS transcription factors, ERG and ETV1, were identified as outliers in prostate cancer. Recurrent gene fusions of the 5' untranslated region of TMPRSS2 to ERG or ETV1 were identified in prostate cancer tissues with outlier expression. Using fluorescence in situ hybridisation, 23 of 29 prostate cancer samples were shown to harbour rearrangements in ERG or ETV1. Cell line experiments suggested that the androgen-responsive promoter elements of TMPRSS2 mediate the overexpression of ETS family members in prostate cancer.",
    journal: "Science", year: 2005, doi: "10.1126/science.1117679", pmid: "16254181", authors: "Tomlins SA, Rhodes DR, Perner S, et al.", paperType: "basic", participants: 29, changedPractice: false,
    findings: ["ERG and ETV1 identified as expression outliers in prostate cancer.", "Recurrent fusion of the TMPRSS2 5' untranslated region to ERG or ETV1.", "Rearrangements in 23 of 29 prostate cancer samples by fluorescence in situ hybridisation.", "The androgen-responsive TMPRSS2 promoter drives ETS overexpression."],
    whatItMeans: "It overturned the belief that recurrent gene fusions belong to leukaemias and sarcomas, and it gave prostate cancer its defining founder event. It is also a methodological landmark: the fusion was found by looking for outliers in expression data rather than down a microscope.",
    caveats: ["Twenty-nine samples in the original fluorescence in situ hybridisation validation.", "Twenty years on, no treatment acts on the fusion.", "It carries almost no prognostic information, which was not clear at the time."],
    links: [link(SRC.tomlins2005), { label: "PubMed", url: pubmed("16254181") }], cancers: [PC], targets: ["erg", "etv1", "tmprss2", "androgen-receptor"], pathways: ["prostate-cancer-signalling", "ar-signaling", "transcription-addiction"], terms: ["gene-fusion", "fish", "driver-mutation"], technologies: ["cytogenetics-fish", "rna-seq"], journals: ["science"] }),
  p({ id: SRC.pettersson2012.paper, name: "The TMPRSS2-ERG rearrangement, ERG expression and prostate cancer outcomes: a cohort study and meta-analysis",
    tldr: "Following 1,180 men for more than twelve years, and then pooling 48 other studies, found that the commonest genetic change in prostate cancer does not predict who does badly.",
    summary: "Among men with prostate cancer in the prospective Physicians' Health Study and Health Professionals Follow-Up Study, rearrangement status was determined by immunohistochemical assessment of ERG protein expression, and Cox models examined associations with biochemical recurrence and lethal disease, defined as distant metastases or cancer-specific mortality. The cohort consisted of 1,180 men treated with radical prostatectomy between 1983 and 2005; during a median follow-up of 12.6 years, 266 men experienced recurrence and 85 developed lethal disease. There was no significant association between ERG overexpression and biochemical recurrence, hazard ratio 0.99, or lethal disease, hazard ratio 0.93. A meta-analysis including 47 additional studies covered 5,074 men followed for biochemical recurrence with 1,623 events and 2,049 men followed for lethal disease with 131 events; TMPRSS2-ERG was associated with stage at diagnosis, risk ratio 1.23 for T3 or above against T2, but not with biochemical recurrence, risk ratio 1.00, or lethal disease, risk ratio 0.99.",
    journal: "Cancer Epidemiology, Biomarkers and Prevention", year: 2012, doi: "10.1158/1055-9965.EPI-12-0042", pmid: "22736790", authors: "Pettersson A, Graff RE, Bauer SR, et al.", paperType: "meta-analysis", participants: 5074, changedPractice: false,
    findings: ["No association between ERG overexpression and biochemical recurrence, hazard ratio 0.99, in 1,180 men followed a median 12.6 years.", "No association with lethal disease, hazard ratio 0.93.", "Meta-analysis over 48 studies: risk ratio 1.00 for recurrence and 0.99 for lethal disease.", "An association with stage at diagnosis, risk ratio 1.23."],
    whatItMeans: "It is the definitive negative result for the commonest genomic alteration in this disease. A man told his tumour carries the TMPRSS2-ERG fusion should be told plainly that it does not make his cancer more dangerous.",
    caveats: ["Surgical cohorts, so it describes men treated with prostatectomy rather than all comers.", "ERG immunohistochemistry is a proxy for the rearrangement rather than the rearrangement itself.", "Meta-analysis over studies with different assays and different endpoints."],
    links: [link(SRC.pettersson2012), { label: "PubMed", url: pubmed("22736790") }], cancers: [PC], targets: ["erg", "tmprss2"], pathways: ["prostate-cancer-signalling", "ar-signaling"], terms: ["gene-fusion", "ihc", "biochemical-recurrence"], technologies: ["histopathology-ihc"], journals: ["cancer-epidemiology-biomarkers-prevention"] }),
];

// ======================= PAPERS, PART D: MISMATCH REPAIR, PSMA, LINEAGE AND PLASMA =======================
const papersD: PaperInput[] = [
  p({ id: SRC.abidaMsi2019.paper, name: "Prevalence of microsatellite instability in prostate cancer and response to immune checkpoint blockade",
    tldr: "Three in a hundred prostate cancers have a broken proofreading system, and in the men who did, immunotherapy worked and kept working.",
    summary: "In a case series, 1,551 tumours from 1,346 men with prostate cancer were prospectively analysed with a targeted sequencing assay between January 2015 and January 2018, with tumour mutation burden and MSIsensor score calculated and mutational signature analysis and mismatch repair immunohistochemistry performed in selected cases. Among the 1,033 men whose tumours were of adequate quality for MSIsensor analysis, 32, 3.1%, had microsatellite instability-high or mismatch repair-deficient prostate cancer: 23 with high MSIsensor scores and a further 9 with indeterminate scores but other evidence of deficient repair. Seven of the 32, 21.9%, had a pathogenic germline mutation in a Lynch syndrome-associated gene. Of the 6 men with more than one tumour analysed, 2 displayed an acquired microsatellite instability-high phenotype later in the disease course. Eleven men with microsatellite instability-high or mismatch repair-deficient castration-resistant disease received anti-PD-1 or anti-PD-L1 therapy: 6, 54.5%, had a PSA decline of more than half, 4 of them with radiographic responses, and 5 of the 6 responders were still on therapy at up to 89 weeks.",
    journal: "JAMA Oncology", year: 2019, doi: "10.1001/jamaoncol.2018.5801", pmid: "30589920", authors: "Abida W, Cheng ML, Armenia J, et al.", paperType: "observational", participants: 1033, changedPractice: true,
    findings: ["Microsatellite instability-high or mismatch repair-deficient disease in 32 of 1,033 men, 3.1%.", "A pathogenic germline Lynch syndrome variant in 7 of the 32, 21.9%.", "The phenotype was acquired during the disease course in 2 of 6 men with serial tumours.", "PSA decline over 50% in 6 of 11 treated men, with 5 still on therapy at up to 89 weeks."],
    whatItMeans: "It is the argument for sequencing every man with advanced prostate cancer rather than only the ones who look high risk: the phenotype is uncommon, it is invisible clinically, it opens the only durable immunotherapy route in this disease, and in one man in five it also identifies Lynch syndrome in the family.",
    caveats: ["A single-centre case series with 11 treated men, so the response rate has wide uncertainty.", "Not all microsatellite instability-high men responded, and the mechanisms of resistance were not defined.", "Because the phenotype can be acquired, a negative result on an old sample does not settle the question."],
    links: [link(SRC.abidaMsi2019), { label: "PubMed", url: pubmed("30589920") }], cancers: [PC, MCRPC], targets: ["msh2", "msh6", "mlh1", "pms2", "mmr", "pd1"], drugs: ["pembrolizumab"], pathways: ["mismatch-repair-msi", "pd1-checkpoint", "cancer-immunity-cycle"], terms: ["msi", "lynch-syndrome", "tumour-agnostic", "germline-vs-somatic", "psa50"], technologies: ["cgp", "checkpoint-inhibitor"], journals: ["jama-oncology"] }),
  p({ id: SRC.pritchard2014.paper, name: "Complex MSH2 and MSH6 mutations in hypermutated microsatellite unstable advanced prostate cancer",
    tldr: "The prostate cancers with a broken proofreading system usually break it by tearing the gene apart rather than by switching it off, which is the opposite of what happens in bowel cancer.",
    summary: "A hypermutated subtype of advanced prostate cancer had been described but its prevalence and mechanism were not characterised. Of 60 advanced prostate cancers examined, 7, 12%, were hypermutated, and all of the hypermutated cancers had mismatch repair gene mutations and microsatellite instability. The mutations were frequently complex MSH2 or MSH6 structural rearrangements rather than MLH1 epigenetic silencing, identifying both parallels and differences with the mechanisms of hypermutation in other microsatellite instability-associated cancers.",
    journal: "Nature Communications", year: 2014, doi: "10.1038/ncomms5988", pmid: "25255306", authors: "Pritchard CC, Morrissey C, Kumar A, et al.", paperType: "basic", participants: 60, changedPractice: false,
    findings: ["Seven of 60 advanced prostate cancers hypermutated, 12%.", "All hypermutated cancers had mismatch repair gene mutations and microsatellite instability.", "Complex MSH2 or MSH6 structural rearrangements rather than MLH1 promoter methylation."],
    whatItMeans: "It matters for how the test is done. A mismatch repair assay designed around the colorectal mechanism, looking for MLH1 promoter methylation and simple mutations, can miss the prostate mechanism entirely, which is one reason microsatellite instability was under-recognised in this disease for so long.",
    caveats: ["Sixty advanced cancers, so the 12% is imprecise and higher than the 3.1% found in a much larger prospectively sequenced series.", "Rapid-autopsy and research material.", "Structural rearrangements are hard to call on short-read panel data, so this mechanism is still under-detected."],
    links: [link(SRC.pritchard2014), { label: "PubMed", url: pubmed("25255306") }], cancers: [PC, MCRPC], targets: ["msh2", "msh6", "mmr"], pathways: ["mismatch-repair-msi", "ddr"], terms: ["msi", "lynch-syndrome", "tmb"], technologies: ["wes-wgs", "cgp"], journals: ["nature-communications"] }),
  p({ id: SRC.guedes2017.paper, name: "MSH2 loss in primary prostate cancer",
    tldr: "Staining more than a thousand prostate tumours found the mismatch repair protein missing in about one in eighty, and twenty times more often in the highest-grade cancers.",
    summary: "A total of 1,133 primary prostatic adenocarcinomas and 43 prostatic small cell carcinomas were screened by MSH2 immunohistochemistry with confirmation by next-generation sequencing, and microsatellite instability was assessed by PCR and by mSINGS. Of the primary adenocarcinomas and small cell carcinomas together, 14 of 1,176, 1.2%, had MSH2 loss. Eight per cent of adenocarcinomas with primary Gleason pattern 5 (Gleason score 9 to 10), 7 of 91, had MSH2 loss compared with 0.4%, 5 of 1,042, of tumours with any other score, and 2 of 43 small cell carcinomas, 5%. MSH2 loss was generally homogeneous, suggesting an early clonal event. Sequencing confirmed loss-of-function alterations in all 12 samples tested, with biallelic inactivation in 83% and hypermutation in 83%; 61% and 58% had definite microsatellite instability by PCR and mSINGS respectively, and 3 patients, 25%, had germline MSH2 mutations. Tumours with MSH2 loss had a higher density of infiltrating CD8-positive lymphocytes than grade-matched controls, 390 against 76 cells per square millimetre.",
    journal: "Clinical Cancer Research", year: 2017, doi: "10.1158/1078-0432.CCR-17-0955", pmid: "28790115", authors: "Guedes LB, Antonarakis ES, Schweizer MT, et al.", paperType: "observational", participants: 1176, changedPractice: false,
    findings: ["MSH2 protein loss in 14 of 1,176 prostate carcinomas, 1.2%.", "Eight per cent of primary Gleason pattern 5 tumours against 0.4% of all others.", "Homogeneous loss, biallelic inactivation in 83% and hypermutation in 83% of sequenced cases.", "Germline MSH2 mutation in 3 of 12 sequenced patients, 25%; CD8 density 390 against 76 cells per square millimetre."],
    whatItMeans: "It gives a cheap way to find the rare men who could benefit from checkpoint blockade: an immunohistochemical stain on the highest-grade primary tumours, where the yield is twenty times higher than average. It also shows the loss is clonal and early, so the diagnostic block is an adequate place to look.",
    caveats: ["MSH2 immunohistochemistry alone, so tumours losing MLH1, MSH6 or PMS2 without MSH2 loss were not counted.", "A single-institution series with retrospective case selection.", "The immune infiltrate finding is descriptive and was not linked to treatment outcome here."],
    links: [link(SRC.guedes2017), { label: "PubMed", url: pubmed("28790115") }], cancers: [PC, NEPC], targets: ["msh2", "mmr"], pathways: ["mismatch-repair-msi", "cancer-immunity-cycle"], terms: ["msi", "ihc", "lynch-syndrome", "gleason-grade-group", "germline-vs-somatic"], technologies: ["histopathology-ihc", "cgp"], journals: ["clinical-cancer-research"] }),
  p({ id: SRC.silver1997.paper, name: "Prostate-specific membrane antigen expression in normal and malignant human tissues",
    tldr: "The survey that mapped where PSMA is found in the body, and showed it is almost nowhere except the prostate, which is what makes it safe to aim a radioactive drug at it.",
    summary: "An extensive immunohistochemical analysis was performed on a panel of well-characterised normal and malignant human tissues to define the pattern of prostate-specific membrane antigen expression. Detectable levels were identified in prostatic epithelium, duodenal mucosa and a subset of proximal renal tubules, and a subpopulation of neuroendocrine cells in the colonic crypts also showed immunoreactivity; all other normal tissues, including cerebral cortex and cerebellum, had undetectable levels. Thirty-three of 35 primary prostate adenocarcinomas and 7 of 8 lymph node metastases showed tumour cell staining, while 8 of 18 prostate tumours metastatic to bone expressed it. All other non-prostatic primary tumours studied had undetectable levels, but intense staining was seen in capillary endothelial cells in peritumoral and endotumoral areas of certain malignancies, including 8 of 17 renal cell carcinomas, 7 of 13 transitional cell carcinomas and 3 of 19 colon carcinomas. The decrease in immunoreactivity in advanced prostate cancer suggested that expression is linked to the degree of tumour differentiation.",
    journal: "Clinical Cancer Research", year: 1997, pmid: "9815541", authors: "Silver DA, Pellicer I, Fair WR, Heston WD, Cordon-Cardo C.", paperType: "basic", changedPractice: false,
    findings: ["Detectable PSMA in normal prostatic epithelium, duodenal mucosa, some proximal renal tubules and colonic neuroendocrine cells only.", "Staining in 33 of 35 primary prostate adenocarcinomas and 7 of 8 lymph node metastases.", "Staining in only 8 of 18 bone metastases, with expression linked to differentiation.", "Neovascular endothelial staining in renal, transitional and colon carcinomas."],
    whatItMeans: "It is the anatomical basis for PSMA imaging and PSMA radioligand therapy, and it predicted two of the practical problems three decades early: salivary, lacrimal and renal uptake as sources of toxicity, and falling expression in dedifferentiated disease as the reason some men are ineligible for treatment.",
    caveats: ["A small immunohistochemical survey from 1997 with the antibodies of the time.", "Eighteen bone metastases is a thin basis for the differentiation claim, although later work supports it.", "It predates PET imaging entirely, so the link to scan positivity is inferred."],
    links: [link(SRC.silver1997), { label: "PubMed", url: pubmed("9815541") }], cancers: [PC, MCRPC], targets: ["psma"], pathways: ["prostate-cancer-signalling"], terms: ["ihc", "theranostics"], technologies: ["histopathology-ihc", "psma-pet", "radioligand-therapy"], journals: ["clinical-cancer-research"] }),
  p({ id: SRC.fendler2019.paper, name: "Accuracy of gallium-68 PSMA-11 PET in localising recurrent prostate cancer: a prospective single-arm clinical trial",
    tldr: "In 635 men whose PSA had started rising again, a PSMA scan found where the cancer was in three quarters of them, and the chance of finding it rose steeply with the PSA level.",
    summary: "In a single-arm prospective trial at two universities, 635 men with biochemically recurrent prostate cancer after prostatectomy (262, 41%), radiation therapy (169, 27%) or both (204, 32%) underwent gallium-68 PSMA-11 PET, with the presence of prostate cancer recorded by three blinded readers on a per-patient and per-region basis and lesions validated by histopathology and by a composite reference standard. Median age was 69 years. Positive predictive value was 0.84 by histopathological validation in 87 men and 0.92 by the composite reference standard in 217 men. The scan localised recurrent prostate cancer in 475 of 635 men, 75%, and detection rates rose significantly with PSA: 38% below 0.5 ng/mL in 136 men, 57% at 0.5 to under 1.0 in 79, 84% at 1.0 to under 2.0 in 89, 86% at 2.0 to under 5.0 in 158 and 97% at 5.0 or above in 173. Interreader reproducibility was substantial, Fleiss kappa 0.65 to 0.78, and there were no serious adverse events. PET-directed focal therapy alone led to a PSA drop of 50% or more in 31 of 39 men, 80%.",
    journal: "JAMA Oncology", year: 2019, doi: "10.1001/jamaoncol.2019.0096", pmid: "30920593", authors: "Fendler WP, Calais J, Eiber M, et al.", paperType: "observational", participants: 635, changedPractice: true,
    findings: ["Recurrence localised in 475 of 635 men, 75%.", "Detection rate 38% below PSA 0.5 ng/mL, rising to 97% at 5.0 or above.", "Positive predictive value 0.84 by histopathology and 0.92 by composite reference standard.", "PSA fall of at least half in 31 of 39 men treated with PET-directed focal therapy alone."],
    whatItMeans: "It is the evidence behind using PSMA PET when PSA rises after treatment, and it quantifies the limit that matters most: below PSA 0.5 ng/mL, where salvage radiotherapy works best, the scan is negative in nearly two men in three, so a negative scan is not a reason to wait.",
    caveats: ["Two academic centres with experienced readers, so performance elsewhere may be lower.", "Histopathological validation was available for only 87 of 635 men.", "The PSA responses to focal therapy show the scan pointed at real disease, not that focal therapy cures."],
    links: [link(SRC.fendler2019), { label: "PubMed", url: pubmed("30920593") }], cancers: [PC], targets: ["psma"], pathways: ["prostate-cancer-signalling"], terms: ["biochemical-recurrence", "psa", "theranostics"], technologies: ["psma-pet", "pet-ct"], journals: ["jama-oncology"] }),
  p({ id: SRC.epstein2014.paper, name: "Proposed morphologic classification of prostate cancer with neuroendocrine differentiation",
    tldr: "A working committee sorted the confusing family of neuroendocrine prostate cancers into named categories, so that a few scattered stained cells would stop being reported in the same words as a small cell carcinoma.",
    summary: "A Prostate Cancer Foundation working committee on the molecular biology and pathologic classification of neuroendocrine differentiation in prostate cancer convened in July 2013, prompted by clinical and molecular data emerging from prostate cancers treated with contemporary androgen deprivation therapies as well as from primary lesions. The resulting classification comprises usual prostate adenocarcinoma with neuroendocrine differentiation; adenocarcinoma with Paneth cell neuroendocrine differentiation; carcinoid tumour; small cell carcinoma; large cell neuroendocrine carcinoma; and mixed neuroendocrine carcinoma with acinar adenocarcinoma. The article also highlights prostate carcinoma with overlapping features of small cell carcinoma and acinar adenocarcinoma, and castration-resistant prostate cancer with a small cell cancer-like clinical presentation.",
    journal: "American Journal of Surgical Pathology", year: 2014, doi: "10.1097/PAS.0000000000000208", pmid: "24705311", authors: "Epstein JI, Amin MB, Beltran H, et al.", paperType: "guideline", changedPractice: true,
    findings: ["Six named categories of prostate cancer with neuroendocrine differentiation.", "Two further descriptive situations for tumours with overlapping features and for clinically small cell-like castration-resistant disease.", "A separation between incidental neuroendocrine staining in ordinary adenocarcinoma and a true neuroendocrine carcinoma."],
    whatItMeans: "It made the reporting of these tumours mean something. The distinction it draws is the one that changes treatment: a few chromogranin-positive cells in an ordinary adenocarcinoma is not the same event as a small cell carcinoma emerging under hormonal treatment, and only the second leads to platinum and etoposide.",
    caveats: ["A consensus proposal rather than an outcome study.", "The categories were defined before the molecular phenotyping that has since split the androgen receptor-null tumours further.", "Interobserver reproducibility of the categories has not been extensively tested."],
    links: [link(SRC.epstein2014), { label: "PubMed", url: pubmed("24705311") }], cancers: [PC, NEPC], targets: ["androgen-receptor"], pathways: ["lineage-plasticity-neuroendocrine"], terms: ["histologic-transformation", "ihc", "castration-resistance"], technologies: ["histopathology-ihc"] }),
  p({ id: SRC.beltran2011.paper, name: "Molecular characterisation of neuroendocrine prostate cancer and identification of new drug targets",
    tldr: "Profiling the rare aggressive form of prostate cancer found two genes amplified together in four out of ten cases, and blocking one of them switched off the neuroendocrine programme.",
    summary: "Using next-generation RNA sequencing and oligonucleotide arrays, 7 neuroendocrine prostate cancers, 30 prostate adenocarcinomas and 5 benign prostate tissues were profiled, with validation on a larger cohort of 37 neuroendocrine cancers, 169 adenocarcinomas and 22 benign tissues using immunohistochemistry and fluorescence in situ hybridisation. Significant overexpression and gene amplification of AURKA and MYCN were found in 40% of neuroendocrine prostate cancers and 5% of adenocarcinomas, with evidence that they cooperate to induce a neuroendocrine phenotype in prostate cells. Neuroendocrine cancers, and MYCN-overexpressing adenocarcinomas, were dramatically sensitive to Aurora kinase inhibitor therapy in vitro and in vivo, with complete suppression of neuroendocrine marker expression after treatment.",
    journal: "Cancer Discovery", year: 2011, doi: "10.1158/2159-8290.CD-11-0130", pmid: "22389870", authors: "Beltran H, Rickman DS, Park K, et al.", paperType: "basic", changedPractice: false,
    findings: ["AURKA and MYCN overexpressed and amplified in 40% of neuroendocrine prostate cancers against 5% of adenocarcinomas.", "The two genes cooperate to induce a neuroendocrine phenotype in prostate cells.", "Aurora kinase inhibition suppressed neuroendocrine marker expression in models."],
    whatItMeans: "It was the first evidence that neuroendocrine prostate cancer is a distinct molecular disease with its own candidate drug target, and it started the programme of Aurora kinase trials in this setting, which have since disappointed.",
    caveats: ["Seven neuroendocrine cancers in the discovery set, which is very few.", "Aurora kinase inhibitors have not shown the activity in men that the models predicted.", "Forty per cent is enrichment within a rare phenotype, not a prostate-wide frequency."],
    links: [link(SRC.beltran2011), { label: "PubMed", url: pubmed("22389870") }], cancers: [PC, NEPC], targets: ["aurka", "mycn"], pathways: ["lineage-plasticity-neuroendocrine", "myc", "mitotic-spindle-checkpoint"], terms: ["histologic-transformation", "gene-amplification", "fish"], technologies: ["rna-seq", "cytogenetics-fish", "histopathology-ihc"], journals: ["cancer-discovery"] }),
  p({ id: SRC.ku2017.paper, name: "Rb1 and Trp53 cooperate to suppress prostate cancer lineage plasticity, metastasis and antiandrogen resistance",
    tldr: "Deleting two tumour suppressor genes in mouse prostate cancer let the tumour change cell type, spread, and shrug off hormone treatment, and a drug that resets the chromatin reversed it.",
    summary: "Studying mouse models, the authors showed that Rb1 loss facilitates lineage plasticity and metastasis of prostate adenocarcinoma initiated by Pten mutation, and that additional loss of Trp53 causes resistance to antiandrogen therapy. Gene expression profiling indicated that the mouse tumours resemble human prostate cancer neuroendocrine variants, and both mouse and human tumours showed increased expression of epigenetic reprogramming factors such as Ezh2 and Sox2. Clinically relevant EZH2 inhibitors restored androgen receptor expression and sensitivity to antiandrogen therapy.",
    journal: "Science", year: 2017, doi: "10.1126/science.aah4199", pmid: "28059767", authors: "Ku SY, Rosario S, Wang Y, et al.", paperType: "basic", changedPractice: false,
    findings: ["Rb1 loss enables lineage plasticity and metastasis in Pten-mutant prostate adenocarcinoma.", "Additional Trp53 loss causes antiandrogen resistance.", "Increased Ezh2 and Sox2 expression in both mouse and human neuroendocrine-like tumours.", "EZH2 inhibition restored androgen receptor expression and antiandrogen sensitivity."],
    whatItMeans: "It turned neuroendocrine transformation from a pathological curiosity into a mechanism with a genotype and a candidate intervention, and it is the reason EZH2 inhibitors are in prostate cancer trials at all.",
    caveats: ["Genetically engineered mouse models, and the human confirmation is correlative.", "EZH2 inhibition has not yet been shown to prevent or reverse transformation in men.", "Loss of RB1 and TP53 is necessary but clearly not sufficient, since most such tumours do not transform."],
    links: [link(SRC.ku2017), { label: "PubMed", url: pubmed("28059767") }], cancers: [PC, MCRPC, NEPC], targets: ["rb1", "tp53", "pten", "ezh2", "sox2", "androgen-receptor"], pathways: ["lineage-plasticity-neuroendocrine", "epigenetic-reprogramming", "p53-cell-cycle", "ar-signaling"], terms: ["histologic-transformation", "resistance", "castration-resistance"], journals: ["science"] }),
  p({ id: SRC.mu2017.paper, name: "SOX2 promotes lineage plasticity and antiandrogen resistance in TP53- and RB1-deficient prostate cancer",
    tldr: "Human prostate cancer cells escaped a hormone-blocking drug by switching to a different cell type, and turning one reprogramming gene off put them back.",
    summary: "Using in vitro and in vivo human prostate cancer models, the authors showed that tumours can develop resistance to the antiandrogen enzalutamide by a phenotypic shift from androgen receptor-dependent luminal epithelial cells to androgen receptor-independent basal-like cells. This lineage plasticity is enabled by the loss of TP53 and RB1 function, is mediated by increased expression of the reprogramming transcription factor SOX2, and can be reversed by restoring TP53 and RB1 function or by inhibiting SOX2 expression.",
    journal: "Science", year: 2017, doi: "10.1126/science.aah4307", pmid: "28059768", authors: "Mu P, Zhang Z, Benelli M, et al.", paperType: "basic", changedPractice: false,
    findings: ["Enzalutamide resistance by a shift from androgen receptor-dependent luminal cells to androgen receptor-independent basal-like cells.", "The shift requires loss of both TP53 and RB1 function.", "SOX2 mediates the shift and knocking it down reverses resistance."],
    whatItMeans: "Published alongside the mouse work, it establishes in human cells that resistance can be a change of cell identity rather than a change in the drug target, which is a different category of problem and needs a different category of answer.",
    caveats: ["Cell line and xenograft models.", "SOX2 is not a druggable target.", "The frequency of this route in men, as opposed to its existence, comes from clinical series rather than from here."],
    links: [link(SRC.mu2017), { label: "PubMed", url: pubmed("28059768") }], cancers: [PC, MCRPC, NEPC], targets: ["tp53", "rb1", "sox2", "androgen-receptor"], pathways: ["lineage-plasticity-neuroendocrine", "epigenetic-reprogramming", "ar-signaling", "cancer-stem-cells-plasticity"], terms: ["histologic-transformation", "resistance"], journals: ["science"] }),
  p({ id: SRC.bluemn2017.paper, name: "Androgen receptor pathway-independent prostate cancer is sustained through FGF signalling",
    tldr: "Over two decades a new kind of advanced prostate cancer appeared that uses neither the androgen receptor nor a neuroendocrine programme, and it runs on a growth factor pathway instead.",
    summary: "Androgen receptor signalling is the distinctive feature of prostate carcinoma and the major therapeutic target in metastatic disease, but androgen receptor antagonism can produce tumours that bypass a functional requirement for the receptor, often through neuroendocrine transdifferentiation. Through molecular assessment of metastatic prostate cancers over two decades, a phenotypic shift was found with the emergence of an androgen receptor-null, neuroendocrine-null phenotype. These double-negative prostate cancers showed elevated FGF and MAPK pathway activity, which can bypass androgen receptor dependence, and pharmacological inhibitors of MAPK or FGFR repressed their growth in vitro and in vivo.",
    journal: "Cancer Cell", year: 2017, doi: "10.1016/j.ccell.2017.09.003", pmid: "29017058", authors: "Bluemn EG, Coleman IM, Lucas JM, et al.", paperType: "basic", changedPractice: false,
    findings: ["An androgen receptor-null, neuroendocrine-null phenotype has emerged in metastatic prostate cancer over two decades.", "Double-negative tumours show elevated FGF and MAPK pathway activity.", "MAPK or FGFR inhibition repressed growth of these tumours in vitro and in vivo."],
    whatItMeans: "It shows that leaving androgen receptor dependence does not have to mean becoming neuroendocrine, and it names a treatable pathway for a group of men whose tumours would otherwise be described only by what they lack.",
    caveats: ["A research autopsy and xenograft series rather than a prospective clinical cohort.", "The phenotypic shift over time is inferred from samples collected under changing treatment practice.", "No FGFR or MEK inhibitor is approved in prostate cancer."],
    links: [link(SRC.bluemn2017), { label: "PubMed", url: pubmed("29017058") }], cancers: [PC, MCRPC, NEPC], targets: ["androgen-receptor", "fgfr1", "mek"], pathways: ["ar-signaling", "fgfr-signalling", "ras-mapk", "lineage-plasticity-neuroendocrine", "resistance-routes-map"], terms: ["resistance", "castration-resistance", "histologic-transformation"], journals: ["cancer-cell"] }),
  p({ id: SRC.labrecque2019.paper, name: "Molecular profiling stratifies diverse phenotypes of treatment-refractory metastatic castration-resistant prostate cancer",
    tldr: "Deep profiling of treatment-resistant prostate cancers found five distinct kinds rather than the two the field had assumed, and gave a 26-gene signature to tell them apart.",
    summary: "Deep phenotypic characterisation of castration-resistant prostate cancer metastases and patient-derived xenograft lines was carried out using whole-genome RNA sequencing, gene set enrichment analysis and immunohistochemistry. The analyses revealed five phenotypes based on expression of well-characterised androgen receptor or neuroendocrine genes: androgen receptor-high tumours, androgen receptor-low tumours, amphicrine tumours composed of cells co-expressing androgen receptor and neuroendocrine genes, double-negative tumours, and tumours with small cell or neuroendocrine gene expression without androgen receptor activity. REST activity, which suppresses neuroendocrine gene expression, was lost in the amphicrine and small cell or neuroendocrine xenograft models, and knockdown experiments showed that attenuated REST activity drives the amphicrine phenotype but is not sufficient for conversion to the small cell or neuroendocrine phenotype. A subtype of double-negative tumours with squamous differentiation was identified, and a 26-gene transcriptional signature distinguishing the five phenotypes was generated.",
    journal: "Journal of Clinical Investigation", year: 2019, doi: "10.1172/JCI128212", pmid: "31361600", authors: "Labrecque MP, Coleman IM, Brown LG, et al.", paperType: "basic", changedPractice: false,
    findings: ["Five phenotypes of castration-resistant disease rather than two: androgen receptor-high, androgen receptor-low, amphicrine, double-negative and small cell or neuroendocrine.", "Loss of REST activity drives the amphicrine phenotype but is not sufficient for small cell conversion.", "A double-negative subtype with squamous differentiation.", "A 26-gene transcriptional signature distinguishing the phenotypes."],
    whatItMeans: "It gives the field a vocabulary for the states between androgen receptor-driven adenocarcinoma and small cell carcinoma, which matters because those in-between tumours are the ones most likely to be mismanaged as ordinary castration-resistant disease.",
    caveats: ["Research metastases and patient-derived xenografts, not a prospective patient cohort.", "The signature needs bulk RNA, which is rarely available from a routine metastatic biopsy.", "No treatment is selected by phenotype today."],
    links: [link(SRC.labrecque2019), { label: "PubMed", url: pubmed("31361600") }], cancers: [PC, MCRPC, NEPC], targets: ["androgen-receptor", "ascl1"], pathways: ["lineage-plasticity-neuroendocrine", "ar-signaling", "transcription-addiction"], terms: ["histologic-transformation", "castration-resistance", "resistance"], technologies: ["rna-seq", "histopathology-ihc"], journals: ["jci"] }),
  p({ id: SRC.aparicio2016.paper, name: "Combined tumour suppressor defects characterise clinically defined aggressive variant prostate cancers",
    tldr: "Prostate cancers that behave like small cell carcinoma without looking like it turn out to share the same broken genes, so the clinical description can be checked against the molecular one.",
    summary: "Morphologically heterogeneous prostate cancers that behave clinically like small cell prostate cancers share their chemotherapy responsiveness. Fifty-nine prostate cancer samples from 40 clinical trial participants meeting aggressive variant criteria, and 8 patient-derived xenografts from 6 of them, were stained for markers aberrantly expressed in small cell prostate cancer, and DNA from 36 samples and 8 xenografts was analysed for copy-number gains and losses. Irrespective of morphology, Ki67 and Tp53 stained in at least 10% of cells in 80% and 41% of samples; RB1 stained in fewer than 10% of cells in 61% and androgen receptor in 36%. MYC copy gain, a surrogate for 8q, and RB1 copy loss were each present in 54% of 44 samples and PTEN copy loss in 48%. All but 1 of 8 xenografts carried Tp53 missense mutations. RB1 copy loss was the strongest discriminator between unselected castration-resistant prostate cancer and the aggressive variant, and combined alterations in RB1, Tp53 and PTEN were more frequent in aggressive variant disease than in unselected castration-resistant disease or in TCGA samples.",
    journal: "Clinical Cancer Research", year: 2016, doi: "10.1158/1078-0432.CCR-15-1259", pmid: "26546118", authors: "Aparicio AM, Shen L, Tapia ELN, et al.", paperType: "translational", participants: 40, changedPractice: false,
    findings: ["RB1 loss the strongest single discriminator between unselected castration-resistant disease and the aggressive variant.", "MYC copy gain and RB1 copy loss each in 54% of 44 samples, PTEN copy loss in 48%.", "RB1 staining in under 10% of cells in 61% of samples and androgen receptor in 36%.", "Combined RB1, TP53 and PTEN alterations enriched in aggressive variant disease."],
    whatItMeans: "It validates a clinical definition against a molecular one, which is unusual and useful: a man whose disease behaves like small cell carcinoma can be treated as such even when his biopsy does not look like it, because the underlying genotype is the same.",
    caveats: ["Fifty-nine samples from 40 trial participants, a selected population.", "Copy-number analysis on archival material rather than sequencing.", "The aggressive variant criteria are clinical and were defined by the same group."],
    links: [link(SRC.aparicio2016), { label: "PubMed", url: pubmed("26546118") }], cancers: [PC, MCRPC, NEPC], targets: ["rb1", "tp53", "pten", "androgen-receptor", "mki67"], pathways: ["lineage-plasticity-neuroendocrine", "p53-cell-cycle", "pi3k-akt-mtor", "chromosomal-instability"], terms: ["histologic-transformation", "ihc", "copy-number-variation-term", "castration-resistance"], technologies: ["histopathology-ihc"], journals: ["clinical-cancer-research"] }),
  p({ id: SRC.berchuck2022.paper, name: "Detecting neuroendocrine prostate cancer through tissue-informed cell-free DNA methylation analysis",
    tldr: "A blood test that reads chemical marks on DNA rather than its letters separated the aggressive neuroendocrine form of prostate cancer from the ordinary form almost perfectly.",
    summary: "Neuroendocrine prostate cancer is a resistance phenotype that emerges in men with metastatic castration-resistant prostate adenocarcinoma and is difficult to detect in practice. Methylated DNA immunoprecipitation and high-throughput sequencing was performed on a training set of tumours, differentially methylated regions between neuroendocrine prostate cancer and castration-resistant adenocarcinoma were identified, and a model was built to predict the presence of neuroendocrine disease, termed a risk score. The same assay was then applied to cell-free DNA from two independent cohorts. The test cohort comprised 48 men, 9 with neuroendocrine disease and 39 with castration-resistant adenocarcinoma; risk scores were significantly higher in the neuroendocrine group and discriminated with an area under the receiver operating curve of 0.96, with the optimal cut-off giving 100% sensitivity and 90% specificity. The validation cohort included 53 men, 12 with neuroendocrine disease and 41 with adenocarcinoma; discrimination was perfect, area under the curve 1.0, and the predefined cut-off gave 100% sensitivity and 95% specificity.",
    journal: "Clinical Cancer Research", year: 2022, doi: "10.1158/1078-0432.CCR-21-3762", pmid: "34907080", authors: "Berchuck JE, Baca SC, McClure HM, et al.", paperType: "translational", participants: 101, changedPractice: false,
    findings: ["Risk score from cell-free DNA methylation discriminated neuroendocrine from castration-resistant adenocarcinoma with an area under the curve of 0.96 in the test cohort.", "One hundred per cent sensitivity and 90% specificity at the optimal cut-off.", "Perfect discrimination in an independent 53-man validation cohort, with 100% sensitivity and 95% specificity at the predefined cut-off."],
    whatItMeans: "It is the right shape of answer for a transition that is epigenetic rather than genetic, and it could in principle spare the biopsy that is currently the only way to make this diagnosis.",
    caveats: ["Twenty-one men with neuroendocrine disease in total across both cohorts, so a perfect area under the curve should be read as promising rather than settled.", "Methylated DNA immunoprecipitation sequencing is a research assay, not one that can be ordered.", "The comparison is against a histological reference standard that is itself imperfect."],
    links: [link(SRC.berchuck2022), { label: "PubMed", url: pubmed("34907080") }], cancers: [PC, MCRPC, NEPC], targets: ["androgen-receptor"], pathways: ["lineage-plasticity-neuroendocrine", "epigenetic-reprogramming"], terms: ["ctdna", "cfdna", "histologic-transformation", "liquid-biopsy"], technologies: ["liquid-biopsy", "methylation-profiling"], journals: ["clinical-cancer-research"] }),
  p({ id: SRC.wyatt2017.paper, name: "Concordance of circulating tumour DNA and matched metastatic tissue biopsy in prostate cancer",
    tldr: "Comparing a blood test with a needle biopsy taken the same day showed that when the blood carried enough tumour DNA, it found everything the biopsy found.",
    summary: "Targeted sequencing across 72 clinically relevant genes was performed on 45 plasma cell-free DNA samples collected at the time of a metastatic tissue biopsy in men with metastatic castration-resistant prostate cancer, and the alterations were compared with exome sequencing data from the matched tissue. Seventy-five point six per cent of the cell-free DNA samples had a circulating tumour DNA proportion greater than 2% of total cell-free DNA. In those men, all somatic mutations identified in the matched metastatic tissue biopsies were concurrently present in circulating tumour DNA, and the hierarchy of variant allele fractions for shared mutations was closely similar between the two. Copy-number profiles between matched liquid and solid biopsy were highly correlated and individual copy-number calls in clinically actionable genes were 88.9% concordant. Detected alterations included AR amplification in 22 samples, 64.7%, SPOP mutation in 3, 8.8%, and inactivating alterations in TP53, PTEN, RB1, APC, CDKN1B, BRCA2 and PIK3R1. In several men, circulating tumour DNA sequencing revealed changes not present in the paired solid biopsy, including alterations in the androgen receptor, WNT and PI3K pathways.",
    journal: "Journal of the National Cancer Institute", year: 2017, doi: "10.1093/jnci/djx118", pmid: "29206995", authors: "Wyatt AW, Annala M, Aggarwal R, et al.", paperType: "translational", participants: 45, changedPractice: false,
    findings: ["Circulating tumour DNA above 2% of total cell-free DNA in 75.6% of samples.", "In those samples, every somatic mutation found in matched tissue was also found in plasma.", "Copy-number calls in actionable genes 88.9% concordant.", "Plasma revealed AR, WNT and PI3K pathway changes absent from the paired tissue in several men."],
    whatItMeans: "It is the study that justified using plasma instead of a bone biopsy in this disease, with the honest caveat attached: the concordance holds only above a tumour fraction threshold, and below it the test is uninformative rather than negative.",
    caveats: ["Forty-five paired samples at academic centres.", "Nearly a quarter of samples fell below the 2% tumour fraction threshold.", "A 72-gene panel, so genes outside it were not compared."],
    links: [link(SRC.wyatt2017), { label: "PubMed", url: pubmed("29206995") }], cancers: [PC, MCRPC], targets: ["androgen-receptor", "tp53", "pten", "rb1", "brca", "spop"], pathways: ["ar-signaling", "wnt", "pi3k-akt-mtor", "clonal-evolution"], terms: ["ctdna", "cfdna", "liquid-biopsy", "biopsy"], technologies: ["liquid-biopsy", "cgp"], journals: ["jnci"] }),
  p({ id: SRC.annala2018.paper, name: "Circulating tumour DNA genomics correlate with resistance to abiraterone and enzalutamide in prostate cancer",
    tldr: "A blood test taken before the first tablet identified the men whose disease would resist both standard hormone drugs, which the clinical variables could not do.",
    summary: "Two hundred and two men with treatment-naive metastatic castration-resistant prostate cancer were randomised to abiraterone or enzalutamide and had whole-exome and deep targeted 72-gene sequencing of plasma cell-free DNA before therapy. Time to progression was similar for the two agents, which had never been directly compared. Defects in BRCA2 and ATM were strongly associated with poor clinical outcomes independently of clinical prognostic factors and of circulating tumour DNA abundance. Somatic alterations in TP53, previously linked to reduced tumour dependency on androgen receptor signalling, were also independently associated with rapid resistance. Detection of AR amplification did not outperform standard prognostic biomarkers, but AR gene structural rearrangements truncating the ligand-binding domain were identified in several men with primary resistance.",
    journal: "Cancer Discovery", year: 2018, doi: "10.1158/2159-8290.CD-17-0937", pmid: "29367197", authors: "Annala M, Vandekerkhove G, Khalaf D, et al.", paperType: "rct", participants: 202, changedPractice: false,
    findings: ["BRCA2 and ATM defects independently associated with poor outcome on either hormonal agent.", "TP53 alterations independently associated with rapid resistance.", "AR amplification detection did not outperform standard prognostic biomarkers.", "AR structural rearrangements truncating the ligand-binding domain found in men with primary resistance.", "Time to progression was similar for abiraterone and enzalutamide."],
    whatItMeans: "It shows that the useful information in a castration-resistant plasma sample is in the repair genes and TP53 rather than in the androgen receptor finding that dominates the report, and it is the closest thing the field has to a head-to-head comparison of abiraterone against enzalutamide.",
    caveats: ["A randomised phase 2 trial, so the drug comparison is not definitive.", "Two hundred and two men at Canadian centres.", "The prognostic associations have not been used prospectively to assign treatment."],
    links: [link(SRC.annala2018), { label: "PubMed", url: pubmed("29367197") }], cancers: [PC, MCRPC], targets: ["brca", "atm", "tp53", "androgen-receptor"], drugs: ["abiraterone", "enzalutamide"], pathways: ["ar-signaling", "homologous-recombination-repair", "p53-cell-cycle", "resistance-routes-map"], terms: ["ctdna", "cfdna", "liquid-biopsy", "resistance", "castration-resistance"], technologies: ["liquid-biopsy", "wes-wgs"], journals: ["cancer-discovery"] }),
  p({ id: SRC.tukachinsky2021.paper, name: "Genomic analysis of circulating tumour DNA in 3,334 patients with advanced prostate cancer identifies targetable BRCA alterations and AR resistance mechanisms",
    tldr: "The largest blood-based study in advanced prostate cancer found detectable tumour DNA in nineteen men out of twenty, agreed with tissue on BRCA faults nine times out of ten, and found resistance changes tissue had missed.",
    summary: "Using plasma from 3,334 men with metastatic castration-resistant prostate cancer, including 1,674 screening samples from the TRITON2 and TRITON3 trials, the landscape of genomic alterations detectable in circulating tumour DNA was evaluated and compared with tissue-based profiling. Three thousand one hundred and twenty-nine men, 94%, had detectable circulating tumour DNA, at a median tumour fraction of 7.5%, and BRCA1 or BRCA2 was mutated in 295, 8.8%. In the concordance analysis, 72 of 837 men had BRCA1 or BRCA2 mutations detected in tissue, of which 67, 93%, were also identified in circulating tumour DNA, including 100% of the variants predicted to be germline. Circulating tumour DNA harboured some BRCA alterations not identified by tissue testing and was enriched for therapy resistance alterations as well as for possible clonal haematopoiesis mutations, for example in ATM and CHEK2. Potential androgen receptor resistance alterations were detected in 940 of 2,213 men, 42%, including amplifications, polyclonal and compound mutations, rearrangements and novel deletions in exon 8.",
    journal: "Clinical Cancer Research", year: 2021, doi: "10.1158/1078-0432.CCR-20-4805", pmid: "33558422", authors: "Tukachinsky H, Madison RW, Chung JH, et al.", paperType: "observational", participants: 3334, changedPractice: true,
    findings: ["Detectable circulating tumour DNA in 3,129 of 3,334 men, 94%, at a median tumour fraction of 7.5%.", "BRCA1 or BRCA2 mutated in 295 men, 8.8%.", "Ninety-three per cent concordance with tissue for BRCA mutations, including 100% of predicted germline variants.", "Potential androgen receptor resistance alterations in 940 of 2,213 men, 42%.", "Enrichment for possible clonal haematopoiesis mutations, notably in ATM and CHEK2."],
    whatItMeans: "It established plasma profiling as a routine alternative to tissue for the BRCA question in advanced prostate cancer, with a sensible rule attached: if plasma finds nothing actionable, go back to tissue. It also documents at scale both the extra resistance information plasma gives and the clonal haematopoiesis noise that comes with it.",
    caveats: ["Half the cohort came from trial screening, so it is enriched for men being considered for a PARP inhibitor.", "One commercial assay, so the performance is that assay's.", "The clonal haematopoiesis mutations were inferred rather than confirmed against a paired blood control."],
    links: [link(SRC.tukachinsky2021), { label: "PubMed", url: pubmed("33558422") }], cancers: [PC, MCRPC], targets: ["brca", "androgen-receptor", "atm", "chek2"], pathways: ["homologous-recombination-repair", "ar-signaling", "clonal-haematopoiesis", "resistance-routes-map"], terms: ["ctdna", "cfdna", "liquid-biopsy", "germline-vs-somatic", "gbrca-mutation"], technologies: ["liquid-biopsy", "cgp"], journals: ["clinical-cancer-research"] }),
];

