/** Target supplements derived from the landscape table: one prevalence row per gene, with every cohort in the note. */
const targetSupplements: SpikeSupplement[] = (() => {
  const byTarget = new Map<string, ProstateLandscapeRow[]>();
  for (const r of prostateMolecularLandscape) if (r.targetId) byTarget.set(r.targetId, [...(byTarget.get(r.targetId) ?? []), r]);
  return [...byTarget.entries()].map(([targetId, rows]) => sup<TargetInput>({
    id: targetId,
    cancers: [PC],
    prevalence: rows.map((row) => ({ cancerId: PC, pct: row.pct, measure: row.alteration, source: row.sources[0].url, note: row.frequency })),
    whereFound: rows.map((row) => `Prostate cancer: ${row.alteration.toLowerCase()} ${typeof row.pct === "number" ? `about ${row.pct}%` : `${row.pct}%`} depending on disease state`),
    keyPapers: [...new Set(rows.flatMap((row) => row.sources.map((s) => PAPER_BY_URL.get(s.url)).filter((x): x is string => !!x)))],
  }));
})();

